comms.text:
@1 וַאֲמַר יְיָ לְאַבְרָם אִיזֵל לָךְ מֵאַרְעָךְ וּמִיַּלָּדוּתָךְ וּמִבֵּית אֲבוּךְ לְאַרְעָא דִּי אַחֲזִנָּךְ:
@2 וְאֶעְבְּדִנָּךְ לְעַם סַגִּי וֶאֱבָרֵכִנָּךְ וַאֲרַבֵּי שְׁמָךְ וּתְהֵא מְבָרֵךְ:
@3 וֶאֱבָרֵךְ מְבָרְכָךְ וּמְלַטְטָךְ אֵילוּט וְיִתְבָּרֲכוּן בְּדִילָךְ כֹּל זַרְעֲיַת אַרְעָא:
@4 וַאֲזַל אַבְרָם כְּמָא דְּמַלֵּיל עִמֵּהּ יְיָ וַאֲזַל עִמֵּהּ לוֹטּ וְאַבְרָם בַּר שִׁבְעִין וַחֲמֵשׁ שְׁנִין בְּמִפְקֵהּ מֵחָרָן:
@5 וּדְבַר אַבְרָם יָת שָׂרַי אִתְּתֵהּ וְיָת לוֹט בַר אֲחוּהִי וְיָת כָּל קִנְיָנְהוֹן דִּי קְנוֹ וְיָת נַפְשָׁתָא דְּשַׁעֲבִּידוּ לְאוֹרַיְתָא בְחָרָן וּנְפָקוּ לְמֵיזַל לְאַרְעָא דִּכְנַעַן וַאֲתוֹ לְאַרְעָא דִּכְנָעַן:
@6 וַעֲבַר אַבְרָם בְּאַרְעָא עַד אֲתַר שְׁכֶם עַד מֵישַׁר מוֹרֶה וּכְנַעֲנָאָה בְּכֵן בְּאַרְעָא:
@7 וְאִתְגְּלִי יְיָ לְאַבְרָם וַאֲמַר לִבְנָךְ אֶתֵּן יָת אַרְעָא הָדָא וּבְנָא תַמָּן מַדְבְּחָא קֳדָם יְיָ דְּאִתְגְּלִי לֵהּ:
@8 וְאִסְתַּלַּק מִתַּמָּן לְטוּרָא מִמַדְנַח לְבֵית אֵל וּפְרַס מַשְׁכְּנֵהּ בֵּית אֵל מִמַּעַרְבָא וְעַי מִמָּדִינְחָא וּבְנָא תַמָּן מִדְבְּחָא קֳדָם יְיָ וְצַלִּי בִּשְׁמָא דַּיְיָ:
@9 וּנְטַּל אַבְרָם אָזֵל וְנָטֵל לְדָרוֹמָא:
@10 וַהֲוָה כַפְנָא בְּאַרְעָא וּנְחַת אַבְרָם לְמִצְרַיִם לְאִתּוֹתָבָא תַמָּן אֲרֵי תַקִּיף כַּפְנָא בְּאַרְעָא:
@11 וַהֲוָה כַּד קְרֵיב לְמֵיעַל לְמִצְרָיִם וַאֲמַר לְשָׂרַי אִתְּתֵה הָא כְעַן יְדָעִית אֲרֵי אִתְּתָא שַׁפִּירַת חֵיזוּ אָתְּ:
@12 וִיהֵי כַּד (נ''י אֲרֵי) יֶחֱזוּן יָתִיךְ מִצְרָאֵי וְיֵימְרוּן אִתְּתֵהּ דָּא וְיִקְטְלוּן יָתִי וְיָתִיךְ יְקַיְמוּן:
@13 אִמְרִי כְעַן אֲחָתִי אָתְּ בְּדִיל דְּיֵיטַב לִי בְּדִילָךְ וְתִתְקַיֵּם נַפְשִׁי בְּפִתְגָּמָיְכִי:
@14 וַהֲוָה כַּד עַל אַבְרָם לְמִצְרָיִם וַחֲזוֹ מִצְרָאֵי יָת אִתְּתָא אֲרֵי שַׁפִּירָא הִיא לַחֲדָא:
@15 וַחֲזוֹ יָתַהּ רַבְרְבֵי פַרְעֹה וְשַׁבָּחוּ יָתַהּ לְפַרְעֹה וְאִדַּבָּרַת אִתְּתָא לְבֵית פַּרְעֹה:
@16 וּלְאַבְרָם אוֹטִיב בְּדִילַהּ וַהֲווֹ לֵהּ עָאן וְתוֹרִין וַחֲמָרִין וְעַבְדִין וְאַמְהָן וְאַתְנָן וְגַמְלִין:
@17 וְאַיְתִי יְיָ עַל פַּרְעֹה מַכְתָּשִׁין רַבְרְבִין וְעַל אֱנַשׁ בֵּיתֵהּ עַל עֵיסַק שָׂרַי אִתַּת אַבְרָם:
@18 וּקְרָא פַרְעֹה לְאַבְרָם וַאֲמַר מָה דָּא עֲבַדְתְּ לִי לְמָא לָא חַוֵּיתָא לִי אֲרֵי אִתְּתָךְ הִיא:
@19 לְמָא אֲמַרְתְּ אֲחָתִי הִיא וּדְבָרִית יָתַהּ לִי לְאִתּוּ וּכְעַן הָא אִתְּתָךְ דְּבַר וְאִיזֵל:
@20 וּפַקִּיד עֲלוֹהִי פַּרְעֹה גּוּבְרִין וְאַלְוִיאוּ יָתֵהּ וְיָת אִתְּתֵהּ וְיָת כָּל דִילֵהּ:
@21 וּסְלֵיק אַבְרָם מִמִּצְרַיִם הוּא וְאִתְּתֵהּ וְכָל דִּילֵהּ וְלוֹט עִמֵּהּ לְדָרוֹמָא:
@22 וְאַבְרָם תַּקִּיף לַחֲדָא בִּבְעִירָא בְּכַסְפָּא וּבְדַהֲבָא:
@23 וַאֲזַל לְמַטְלָנוֹהִי מִדָּרוֹמָא וְעַד בֵּית אֵל עַד אַתְרָא דִּי פְּרַס תַּמָּן מַשְׁכְּנֵהּ בְּקַדְמֵיתָא בֵּין בֵּית אֵל וּבֵין עָי:
@24 לַאֲתַר מַדְבְּחָא דִּי עֲבַד תַּמָּן בְּקַדְמֵיתָא וְצַלֵּי תַמָּן אַבְרָם בִּשְׁמָא דַּיְיָ:
@25 וְאַף לְלוֹט דְּאָזִיל עִם אַבְרָם הֲוָה עָאן וְתוֹרִין וּמַשְׁכְּנִין:
@26 וְלָא סוֹבָרַת יָתְהוֹן אַרְעָא לְמִיתַב כַּחֲדָא אֲרֵי הֲוָה קִנְיָנְהוֹן סַגִּי וְלָא יְכִילוּ לְמִיתַּב כַּחֲדָא:
@27 וַהַוַת מַצוּתָא בֵּין רָעֵי בְּעִירֵה דְאַבְרָם וּבֵין רָעֵי בְּעִירֵה דְלוֹט וּכְנַעֲנָאָה וּפְרִזָאָה בְּכֵן יָתִיב בְּאַרְעָא:
@28 וַאֲמַר אַבְרָם לְלוֹט לָא כְעַן תְּהֵי מַצוּתָא בֵּינָא וּבֵינָךְ וּבֵין רַעֲוָתִי וּבֵין רַעֲוָתָךְ אֲרֵי גוּבְרִין אַחִין אֲנָחְנָא:
@29 הֲלָא כָל אַרְעָא קֳדָמָךְ אִתְפָּרַשׁ כְּעַן מִלְוָתִי אִם אַתְּ לְצִפּוּנָא וַאֲנָא לְדָרוֹמָא וְאִם אַתְּ לְדָרוֹמָא וַאֲנָא לְצִפּוּנָא:
@30 וּזְקַף לוֹט יָת עֵינוֹהִי וַחֲזָא יָת כָּל מֵישַׁר יַרְדְנָא אֲרֵי כֻלַהּ בֵּית שַׁקְיָא קֳדָם חַבָּלוּת יְיָ יָת סְדוֹם וְיָת עֲמֹרָא כְּגִנְתָא דַיְיָ כְּאַרְעָא דְמִצְרַיִם מָטֵּי לְצוֹעַר:
@31 וּבְחַר לֵיהּ לוֹט יַת כָּל מֵישַׁר יַרְדְנָא וּנְטַל לוֹט מִלְקַדְמִין וְאִתַּפְרָשׁוּ גְבַר מִלְוַת אָחוּהִי:
@32 אַבְרָם יָתֵיב בְּאַרְעָא דִכְנָעַן וְלוֹט יָתֵיב בְּקִרְוֵי מֵישְׁרָא וּפְרַס עַד סְדוֹם:
@33 וֶאֱנָשִׁין דִסְדוֹם בִּישִׁין בְּמָמוֹנְהוֹן וְחַיָבִין בִּגְוִיָתְהוֹן קֳדָם יְיָ לַחֲדָא:
@34 וַיְיָ אֲמַר לְאַבְרָם בָּתַר דְאִתְפָּרֶשׁ לוֹט מֵעִמֵהּ זְקוֹף כְּעַן עֵינָךְ וַחֲזֵי מִן אַתְרָא דְאַתְּ תַּמָן לְצִפּוּנָא וּלְדָרוֹמָא וּלְמַדִינְחָא וּלְמַעֲרָבָא:
@35 אֲרֵי יָת כָּל אַרְעָא דִי אַתְּ חָזֵי לָךְ אֶתְּנִנַהּ וְלִבְנָיךְ עַד עָלָם:
@36 וֶאֱשַׁוֵּי יָת בְּנָיךְ סַגִיאִין כְּעַפְרָא דְאַרְעָא כְּמָא דִי לָא אֶפְשַׁר לִגְבַר לְּמִמְנֵי יָת עַפְרָא דְאַרְעָא אַף בְּנָיךְ לָא יִתִּמְנוּן:
@37 קוּם הֲלִיךְ בְּאַרְעָא לְאָרְכַּהּ וְלִפְתָיַהּ אֲרֵי לָךְ אֶתְּנִינַהּ:
@38 וּפְרַס אַבְרָם וַאֲתָא וִיתֵב בְּמֵישְׁרֵי מַמְרֵא דִי בְחֶבְרוֹן וּבְנָא תַמָן מַדְבְּחָא קֳדָם יְיָ:
@39 וַהֲוָה בְיוֹמֵי אַמְרָפֶל מַלְכָּא דְבָבֶל אַרְיוֹךְ מַלְכָּא דְאֶלָסָר כְּדָרְלָעוֹמֶר מַלְכָּא דְעֵילָם וְתִדְעָל מַלְכָּא דְעַמְמֵי:
@40 סְדָרוּ (נ''א עֲבָדוּ) קְרָבָא עִם בֶּרַע מַלְכָּא דִסְדוֹם וְעִם בִּרְשַׁע מַלְכָּא דַעֲמֹרָה שִׁנְאָב מַלְכָּא דְאַדְמָה וְשֶׁמְאֵבֶר מַלְכָּא דִצְבוֹיִם וּמַלְכָּא דְבֶלַּע הִיא צוֹעַר:
@41 כָּל אִלֵין אִתְכְּנָשׁוּ לְמֵישַׁר חַקְלַיָא הוּא אֲתַר יַמָא דְמִלְחָא:
@42 תַּרְתֵּי עַשְׂרֵי שְׁנִין פְּלָחוּ יָת כְּדָרְלָעוֹמֶר וּתְלָת עֶשְׂרֵי שְׁנִין מְרָדוּ:
@43 וּבְאַרְבַּע עֶשְׂרֵי שְׁנִין אֲתָא כְּדָרְלָעֹמֶר וּמַלְכַיָא דְעִמֵהּ וּמְחוֹ יָת גִבָּרַיָא דִי בְעַשְׁתְּרוֹת קַרְנַיִם וְיָת תַּקִיפַיָא דִבְהֶמְתָּא וְיָת אֵמְתָנֵי דִבְשָׁוֵה קִרְיָתָיִם:
@44 וְיָת חוֹרָאֵי דִי בְּטוּרְהוֹן דְשֵׂעִיר עַד מֵישַׁר פָּארָן דִסְמִיךְ עַל מַדְבְּרָא:
@45 וְתָבוּ וַאֲתוּ לְמֵישַׁר פִּלּוּג דִינָא הִיא רְקָם וּמְחוֹ יָת כָּל חֲקַל עֲמַלְקָאָה וְאַף יָת אֱמוֹרָאָה דְיָתֵיב בְּעֵין גֶּדִי:
@46 וּנְפַק מַלְכָּא דִסְדוֹם וּמַלְכָּא דַעֲמוֹרָה וּמַלְכָּא דְאַדְמָה וּמַלְכָּא דִצְבוֹיִם וּמַלְכָּא דְבֶלַע הִיא צוֹעַר וְסַדָרוּ עִמְהוֹן קְרָבָא בְּמֵישַׁר חַקְלַיָא:
@47 עִם כְּדָרְלָעֹמֶר מַלְכָּא דְעֵילָם וְתִדְעָל מַלְכָּא דְעַמְמִין וְאַמְרָפֶל מַלְכָּא דְבָבֶל וְאַרְיוֹךְ מַלְכָּא דְאֶלָסָר אַרְבְּעָה מַלְכִין לָקֳבֵיל חַמְשָׁא:
@48 וּמֵישַׁר חַקְלַיָא בֵּירִין בֵּירִין מַסְקַן חֵימָרָא וַעֲרָקוּ מַלְכָּא דִסְדוֹם וַעֲמוֹרָה וּנְפָלוּ תַמָן וּדְאִשְׁתָּאֲרוּ לְטוּרָא עֲרָקוּ:
@49 וּשְׁבוֹ יָת כָּל קִנְיָנָא דִסְדוֹם וַעֲמוֹרָה וְיָת כָּל מֵיכָלְהוֹן וַאֲזָלוּ:
@50 וּשְׁבוֹ יָת לוֹט וְיָת קִנְיָנֵהּ בַּר אַחוּהִי דְאַבְרָם וַאֲזָלוּ וְהוּא יָתֵיב בִּסְדוֹם:
@51 וַאֲתָא מְשֵׁיזָבָא וְחַוִּי לְאַבְרָם עִבְרָאָה וְהוּא שָׁרֵי בְּמֵישְׁרֵי מַמְרֵא אֱמוֹרָאָה אֲחוּהִי דְאֶשְׁכּוֹל וַאֲחוּהִי דְעָנֵר וְאִינוּן אֱנָשֵׁי קְיָמֵהּ דְאַבְרָם:
@52 וּשְׁמַע אַבְרָם אֲרֵי אִשְׁתְּבִי אֲחוּהִי וְזָרֵיז יָת עוּלֵמוֹהִי יְלִידֵי בֵיתֵהּ תְּלַת מְאָה וְתַמְנֵי עֲסַר וּרְדַף עַד דָן:
@53 וְאִתְפְּלֵג עֲלֵיהוֹן לֵילְיָא הוּא וְעַבְדוֹהִי וּמְחוֹנוּן וּרְדָפִנוּן עַד חוֹבָא דִי מִצִפּוּנָא לְדַמָשֶׂק:
@54 וַאֲתֵיב יָת כָּל קִנְיָנָא וְאַף יָת לוֹט בַּר אֲחוּהִי וְקִנְיָנֵהּ אֲתֵיב וְאַף יָת נְשַׁיָא וְיָת עַמָא:
@55 וּנְפַק מַלְכָּא דִסְדוֹם לְקַדָמוּתֵה בָּתַר דְתָב מִלְמִמְחֵי יָת כְּדָרְלָעוֹמֶר וְיָת מַלְכַיָא דִי עִמֵהּ לְמֵישַׁר מַפְנָא הוּא אֲתַר בֵּית רֵיסָא דְמַלְכָּא:
@56 וּמַלְכִּי צֶדֶק מַלְכָּא דִירוּשְׁלֶם אַפֵּיק לְחֵם וַחֲמָר וְהוּא מְשַׁמֵשׁ קֳדָם אֵל עִלָאָה:
@57 וּבָרְכֵיהּ וַאֲמָר בְּרִיךְ אַבְרָם לְאֵל עִלָאָה דְקִנְיָנֵהּ שְׁמַיָא וְאַרְעָא:
@58 וּבְרִיךְ אֵל עִלָאָה דִמְסַר סָנְאָיךְ בִּידָךְ וִיהַב לֵיהּ חַד מִן עַשְׂרָא מִכֹּלָא:
@59 וַאֲמַר מַלְכָּא דִסְדוֹם לְאַבְרָם הַב לִי נַפְשָׁתָא וְקִנְיָנָא (סַב) דְבַר לָךְ:
@60 וַאֲמַר אַבְרָם לְמַלְכָּא דִסְדוֹם אֲרֵמִית יְדַי בִּצְלוֹ קֳדָם יְיָ אֵל עִלָאָה דְקִנְיָנֵהּ שְׁמַיָא וְאַרְעָא:
@61 אִם מִחוּטָא וְעַד עַרְקַת מְסָנָא וְאִם אֶסַב מִכָּל דִי לָךְ וְלָא תֵימַר אֲנָא אַעְתָּרִית יָת אַבְרָם:
@62 לְחוֹד (בַּר) מִדִאֲכָלוּ עוּלֵמַיָא וְחָלָק גֻבְרַיָא דִי אֲזָלוּ עִמִי עָנֵר אֶשְׁכּוֹל וּמַמְרֵא אִינוּן יְקַבְּלוּן חַלָקְהוֹן:
@63 בָּתַר פִּתְגָמַיָא הָאִלֵין הֲוָה פִּתְגָמָא דַיְיָ עִם אַבְרָם בִּנְבוּאָה לְמֵימָר לָא תִדְחַל אַבְרָם מֵימְרִי תְּקוֹף לָךְ אַגְרָךְ סַגִי לַחֲדָא:
@64 וַאֲמַר אַבְרָם יְיָ אֱלֹהִים מַה תִּתֶּן לִי וַאֲנָא אָזֵיל בְּלָא וְלָד וּבַר פַּרְנָסָא הָדֵין דִבְּבֵיתִי הוּא דַמַשְׂקָאָה אֱלִיעֶזֶר:
@65 וַאֲמַר אַבְרָם הָא לִי לָא יְהַבְתְּ וְלָד וְהָא בַר בֵיתִי יָרִיתּ יָתִי:
@66 וְהָא פִּתְגָמָא דַיְיָ עִמֵהּ לְמֵימַר לָא יִרְתִינָךְ דֵין אֱלָהֵין בַּר דְתוֹלִיד הוּא יִרְתִינָךְ:
@67 וְאַפֵּיק יָתֵהּ לְבָרָא וַאֲמַר אִסְתְּכִי כְעַן לִשְׁמַיָא וּמְנֵי כּוֹכְבַיָא אִם תִּכּוֹל לְמִמְנֵי יָתְהוֹן וַאֲמַר לֵיהּ כְּדֵין יְהוֹן בְּנָךְ:
@68 וְהֵימִין בְּמֵימְרָא דַיְיָ וְחָשְׁבַהּ לֵיהּ לְזָכוּ:
@69 וַאֲמַר לֵהּ אֲנָא יְיָ דְאַפֵּקְתָּךְ מֵאוּרָא דְכַשְׂדָאֵי לְמִתַּן לָךְ יָת אַרְעָא הָדָא לְמֵירְתַהּ:
@70 וַאֲמָר יְיָ אֱלֹהִים בְּמָה אִידַע אֲרֵי אֵרְתִנַהּ:
@71 וַאֲמַר לֵהּ קָרֵב קֳדָמַי עֶגְלִין תְּלָתָא וְעִזִין תְּלָתָא וְדִכְרִין תְּלָת וְשַׁפְנִינָא וּבַר יוֹנָה:
@72 וְקָרֵב קֳדָמוֹהִי יָת כָּל אִלֵין וּפַלִיג יָתְהוֹן בְּשָׁוֶה וִיהַב פַּלְגַיָא פִּלוּג לָקֳבֵיל חַבְרֵיהּ וְיָת עוֹפָא לָא פַּלִיג:
@73 וּנְחַת עוֹפָא עַל פַּגְלַיָא וְאַפְרַח יָתְהוֹן אַבְרָם:
@74 וַהֲוָה שִׁמְשָׁא לְמֵיעַל וְשִׁינְתָא נְפָלַת עַל אַבְרָם וְהָא אֵימָתָא קְבֵל סַגִי נְפָלַת עֲלוֹהִי:
@75 וַאֲמַר לְאַבְרָם מִדַע תִּדַע אֲרֵי דַיָרִין יְהוֹן בְּנָיךְ בְּאַרְעָא דְלָא דִילְהוֹן וְיִפְלְחוּן בְּהוֹן וִיעַנוּן יָתְהוֹן אַרְבַּע מְאָה שְׁנִין:
@76 וְאַף יָת עַמָא דְיִפְלְחוּן בְּהוֹן דָיִין אֲנָא וּבָתַר כֵּן יִפְקוּן בְּקִנְיָנָא סַגִי:
@77 וְאַתְּ תֵעוֹל לְוָת אַבָהָתָךְ בִּשְׁלָם תִּתְקְבַר בְּסֵיבוּ טָבָא:
@78 וְדָרָא רְבִיעָאָה יְתוּבוּן הָכָא אֲרֵי לָא שְׁלִים חוֹבָא דֶאֱמוֹרָאָה עַד כְּעָן:
@79 וַהֲוָה שִׁמְשָׁא עַלַת וְקִבְלָא הֲוָה וְהָא תַּנוּר דִתְנַן וּבָעוּר דְאֶשָׁתָא דִעֲדָא בֵּין פַּלְגַיָא הָאִלֵין:
@80 בְּיוֹמָא הַהוּא גְזַר יְיָ עִם אַבְרָם קְיָם לְמֵימָר לִבְנָךְ יְהָבִית יָת אַרְעָא הָדָא מִן נַהֲרָא דְמִצְרַיִם וְעַד נַהֲרָא רַבָּא נַהֲרָא פְרָת:
@81 יָת שַׁלְמָאֵי וְיָת קְנִזָאֵי וְיָת קַדְמוֹנָאֵי:
@82 וְיָת חִתָּאֵי וְיָת פְּרִזָאֵי וְיָת גִבָּרָאֵי:
@83 וְיָת אֱמוֹרָאֵי וְיָת כְנַעֲנָאֵי וְיָת גִרְגָשָׁאֵי וְיָת יְבוּסָאֵי:
@84 וְשָׂרַי אִתַּת אַבְרָם לָא יְלִידַת לֵהּ וְלַהּ אַמְתָא מִצְרֵיתָא וּשְׁמַהּ הָגָר:
@85 וַאֲמַרַת שָׂרַי לְאַבְרָם הָא כְעַן מַנְעֲנִי יְיָ מִלְמֵילַד עוּל כְּעַן לְוַת אַמְתִי מָאִים אִתְבְּנֵי מִנַהּ וְקַבִּיל אַבְרָם לְמֵימַר שָׂרָי:
@86 וּדְבָרַת שָׂרַי אִתַּת אַבְרָם יָת הָגָר מִצְרֵיתָא אַמְתַהּ מִסוֹף עֲשַׂר שְׁנִין לְמִיתַּב אַבְרָם בְּאַרְעָא דִכְנָעַן וִיהָבַת יָתַהּ לְאַבְרָם בַּעֲלַהּ לֵהּ לְאִנְתּוּ:
@87 וְעַל לְוַת הָגָר וְעַדִיאַת וַחֲזַת אֲרֵי עֲדִיאַת וּקְלַת רִבָּנְתַּהּ בְּעֵינָהַהּ:
@88 וַאֲמַרַת שָׂרַי לְאַבְרָם דִין לִי עֲלָךְ אֲנָא יְהָבִית אַמְתִי לָךְ וַחֲזַת אֲרֵי עֲדִיאַת וּקְלֵית בְּעֵינָהַהּ יְדִין יְיָ בֵּינִי וּבֵינָךְ:
@89 וַאֲמַר אַבְרָם לְשָׂרַי הָא אַמְתִיךְ בִּידִךְ עִבִידִי לַהּ כִּדְתַקִין בְעֵינָיְכִי וְעֲנִיתַהּ שָׂרַי וְעָרְקַת מִקֳדָמָהַהּ:
@90 וְאַשְׁכְּחַהּ מַלְאָכָא דַיְיָ עַל עֵינָא דְמַיָא בְּמַדְבְּרָא עַל עֵינָא בְּאָרְחָא דְחַגְרָא:
@91 וַאֲמַר הָגָר אַמְתָא דְשָׂרַי מְנָן אַתְּ אָתְיָא וּלְאָן אַתְּ אָזְלָא וַאֲמַרַת מִן קֳדָם שָׂרַי רִבָּנְתִּי אֲנָא עֲרָקָא (עֲרָקַת):
@92 וַאֲמַר לַהּ מַלְאֲכָא דַיְיָ תּוּבִי לְוַת רִבּוֹנְתִּיךְ וְאִשְׁתַּעְבְּדִי תְּחוֹת יְדָהָא:
@93 וַאֲמַר לַהּ מַלְאֲכָא דַיְיָ אַסְגָאָה אַסְגֵי יָת בְּנָיְכִי וְלָא יִתִּמְנוּן מִסְגֵי:
@94 וַאֲמַר לַהּ מַלְאֲכָא דַיְיָ הָא אַתְּ מְעַדְיָא וְתֵלְדִין בַּר וְתִקְרִין שְׁמֵהּ יִשְׁמָעֵאל אֲרֵי קַבִּיל יְיָ צְלוֹתִיךְ:
@95 וְהוּא יְהֵא מָרוֹד בֶּאֱנָשָׁא הוּא יְהֵא צְרִיךְ לְכֹלָא וְאַף כָּל בְנֵי אֲנָשָׁא יְהוֹן צְרִיכִין לֵהּ וְעַל אַפֵּי כָל אֲחוֹהִי יִשְׁרֵי:
@96 וְצַלִיאַת בִּשְׁמָא דַיְיָ דְמִתְמַלֵל עִמַהּ אֲמַרַת אַתְּ הוּא אֱלָהָא דְחָזֵי כֹלָא אֲרֵי אֲמַרַת הַבְרַם הָכָא (נ''א הַאַף אֲנָא) שָּׁרֵיתִי חַזְיָא בָּתַר דְאִתְגְלִי לִי:
@97 עַל כֵּן קְרָא לִבְאֵרָא בְּאֵרָא דְמַלְאַךְ קַיָימָא אִתַּחֲזִי עֲלַהּ הָא הִיא בֵּין רְקָם וּבֵין חַגְרָא:
@98 וִילִידַת הָגָר לְאַבְרָם בָּר וקְרָא אַבְרָם שׁוּם בְּרֵיהּ דִילִידַת הָגָר יִשְׁמָעֵאל:
@99 וְאַבְרָם בַּר תְּמָנָן וְשִׁית שְׁנִין כַּד יְלִידַת הָגָר יָת יִשְׁמָעֵאל לְאַבְרָם:
@100 וַהֲוָה אַבְרָם בַּר תִּשְׁעִין וּתְשַׁע שְׁנִין וְאִתְגְלִי יְיָ לְאַבְרָם וַאֲמַר לֵיהּ אֲנָא אֵל שַׁדַי פְּלַח קֳדָמַי וֶהֱוֵי שְׁלִים:
@101 וְאֶתֵּן קְיָמִי בֵּין מֵימְרִי וּבֵינָךְ וְאַסְגֵי יָתָךְ לַחֲדָא לַחֲדָא:
@102 וּנְפַל אַבְרָם עַל אַפּוֹהִי וּמַלֵיל עִמֵהּ יְיָ לְמֵימָר:
@103 אֲנָא הָא (גְזַר) קְיָמִי עִמָךְ וּתְהֵי לְאַב סַגִי עַמְמִין:
@104 וְלָא יִתְקְרֵי עוֹד יָת שְׁמָּךְ אַבְרָם וִיהֵי שְׁמָךְ אַבְרָהָם אֲרֵי אַב סַגִי עַמְמִין יְהָבִתָךְ:
@105 וְאַפִּישׁ יָתָךְ לַחֲדָא לַחֲדָא וְאֶתְּנִנָךְ לְכִנְשִׁין וּמַלְכִין דְשַׁלִיטִין בְּעַמְמַיָא מִנָךְ יִפְקוּן:
@106 וַאַקֵים יָת קְיָמִי בֵּין מֵימְרִי וּבֵינָךְ וּבֵין בְּנָךְ בַּתְרָךְ לְדָרֵיהוֹן לִקְיָם עָלָם לְמֵהֲוֵי לָךְ לֵאלָהָא וְלִבְנָיךְ בַּתְרָךְ:
@107 וְאֶתֵּן לָךְ וְלִבְנָיךְ בַּתְרָךְ יָת אַרְעָא תּוֹתָבוּתָךְ יָת כָּל אַרְעָא דִכְנַעַן לְאַחֲסָנַת עָלָם וְאֱהֶוֵי לְהוֹן לֵאלָהָא:
@108 וַאֲמַר יְיָ לְאַבְרָהָם וְאַתְּ יָת קְיָמִי תִטָר אַתְּ וּבְנָךְ בַּתְרָךְ לְדָרֵיהוֹן:
@109 דָא קְיָמִי דִי תִטְרוּן בֵּין מֵימְרִי וּבֵינֵיכוֹן וּבֵין בְּנָיךְ בַּתְרָךְ מִגְזַר לְכוֹן כָּל דְכוּרָא:
@110 וְתִגְזְרוּן יָת בִּשְׂרָא דְעָרְלָתְכוֹן וּתְהֵי (נ''י וּתְהֵא) לְאָת קְיָם בֵּין מֵימְרִי וּבֵינֵיכוֹן:
@111 וּבַר תְּמַנְיָא יוֹמִין יִתְגְזַר (יִגְזַר) לְכוֹן כָּל דְכוּרָא לְדָרָתֵיכוֹן יְלִידֵי בֵּיתָא וּזְבִינֵי כַּסְפָּא מִכֹּל בַּר עַמְמִין דְלָא מִבְּנָךְ הוּא:
@112 אִתְגַזָרָא יִתְגַזְרוּן (נ''י מִגְזַר יִגְזַר) יְלִיד בֵּיתָךְ וּזְבִין כַּסְפָּךְ וּתְהֵי קְיָמִי בְּבִשְׂרֵיכוֹן לִקְיָם עָלָם:
@113 וְעָרֵל דְכוּרָא דִי לָא יִגְזַר יָת בְּשַׂר עָרְלָתֵהּ וְיִשְׁתֵּיצֵי אֱנָשָׁא הַהוּא מֵעַמֵּיהּ יָת קְיָמִי אַשְׁנִי:
@114 וַאֲמַר יְיָ לְאַבְרָהָם שָׂרַי אִתְּתָךְ לָא תִקְרֵי יָת שְׁמַהּ שָׂרָי אֲרֵי שָׂרָה שְׁמַהּ:
@115 וֶאֱבָרֵךְ יָתַהּ וְאַף אֶתֵּן מִנַהּ לָךְ בָּר וֶאֱבָרֲכִנַהּ וּתְהֵי לְכִנְשִׁין מַלְכִין דְשַׁלִּיטִין בְעַמְמַיָּא מִנַהּ יְהוֹן:
@116 וּנְפַל אַבְרָהָם עַל אַפּוֹהִי וַחֲדִי וַאֲמַר בְּלִבֵּהּ הַלְּבַר מְאָה שְׁנִין יְהֵי וְלַד וְאִם שָׂרָה הֲבַת תִּשְׁעִין שְׁנִין תְּלִיד:
@117 וַאֲמַר אַבְרָהָם קֳדָם יְיָ לְוַי יִשְׁמָעֵאל יִתְקַיָּם קֳדָמָךְ:
@118 וַאֲמַר יְיָ בְּקוּשְׁטָא שָׂרָה אִתְּתָךְ תְּלִיד לָךְ בָּר וְתִקְרֵי יָת שְׁמֵהּ יִצְחָק וַאֲקִים יָת קְיָמִי עִמֵּהּ לִקְיָם עָלָם לִבְנוֹהִי בַּתְרוֹהִי:
@119 וְעַל יִשְׁמָעֵאל קַבֵּלִית צְלוֹתָךְ הָא בָּרֵכִית יָתֵהּ וְאַפֵּישּׁ יָתֵהּ וְאַסְגֵּי יָתֵהּ לַחֲדָא לַחֲדָא תְּרֵין עֲשַׂר רַבְרְבַיָּא יְלִיד וְאֶתְּנִנֵּיהּ לְעַם סַגִּי:
@120 וְיָת קְיָמִי אָקִים עִם יִצְחָק דִי תְלִיד לָךְ שָׂרָה לְזִמְנָא הָדֵין בְּשַׁתָּא אָחֳרַנְתָּא:
@121 וְשֵׁיצֵי לְמַלָּלָא עִמֵהּ וְאִסְתַּלַּק יְקָרָא דַיְיָ מֵעִלָּווֹהִי דְּאַבְרָהָם:
@122 וּדְבַר אַבְרָהָם יָת יִשְׁמָעֵאל בְּרֵהּ וְיָת כָּל יְלִידֵי בֵיתֵהּ וְיָת כָּל זְבִינֵי כַסְפֵּה כָּל דְּכוּרָא בַּאֲנָשֵׁי בֵּית אַבְרָהָם וּגְזַר יָת בִּשְׂרָא דְעָרְלָתְהוֹן בִּכְרַן יוֹמָא הָדֵין כְּמָא דִי מַלֵיל עִמֵּהּ יְיָ:
@123 וְאַבְרָהָם בַּר תִּשְׁעִין וּתְשַׁע שְׁנִין כַּד גְזַר בִּשְׂרָא דְעָרְלְתֵהּ:
@124 וְיִשְׁמָעֵאל בְּרֵהּ בַּר תְּלַת עַשְׂרֵי שְׁנִין כַּד גְּזַר יַת בִּשְׂרָא דְעָרְלְתֵהּ:
@125 בִּכְרַן יוֹמָא הָדֵין (גְּזַר) אִתְגְּזַר אַבְרָהָם וְיִשְׁמָעֵאל בְּרֵהּ:
@126 וְכָל אֱנָשֵׁי בֵיתֵהּ יְלִידֵי בֵיתָא וּזְבִינֵי כַסְפָּא מִן בַּר עַמְמִין אִתְגְּזָרוּ (גְזָרוּ) עִמֵּהּ: פפפ:

@1 **לך לך.** להנאתך ולטובתך, ושם אעשך לגוי גדול, וכאן אי אתה זוכה לבנים. ועוד שאודיע טבעך בעולם:
@2 **ואעשך לגוי גדול.** לפי שהדרך גורמת לשלשה דברים ממעטת פריה ורביה, וממעטת את הממון, וממעטת את השם, לכך הזקק לשלש ברכות הללו שהבטיחו על הבנים, ועל הממון, ועל השם. (וזהו ואגדלה שמך, הריני מוסיף אות על שמך, שעד עכשיו שמך אברם מכאן ואלך אברהם, ואברהם עולה רמ''ח כנגד איבריו של אדם) : **ואברכך.** בממון: **והיה ברכה.** הברכות נתנות בידך, עד עכשיו היו בידי, ברכתי את אדם ואת נח ואותך, ומעכשיו אתה תברך את אשר תחפוץ. דבר אחר ואעשך לגוי גדול זהו שאומרים אלהי אברהם, ואברכך זהו שאומרים אלהי יצחק, ואגדלה שמך זהו שאומרים אלהי יעקב. יכול יהיו חותמין בכלן, תלמוד לומר והיה ברכה, בך חותמין ולא בהם: **מארצך.** והלא כבר יצא משם עם אביו ובא עד לחרן, אלא כך אמר לו התרחק עוד משם וצא מבית אביך: **אל הארץ אשר אראך.** לא גלה לו הארץ מיד, כדי לחבבה בעיניו, ולתת לו שכר על כל דבור ודבור. כיוצא בו (בראשית כב ב) את בנך את יחידך אשר אהבת את יצחק, כיוצא בו (כב ב) על אחד ההרים אשר אמר אליך, כיוצא בו (יונה ג ב) וקרא עליה את הקריאה אשר אנכי דובר אליך:
@3 **ונברכו בך כל משפחת האדמה.** יש אגדות רבות, וזהו פשוטו אדם אומר לבנו תהא כאברהם, וכן כל ונברכו בך שבמקרא, וזה מוכיח (בראשית מח כ) בך יברך ישראל לאמר ישימך אלהים כאפרים וכמנשה:
@5 **אשר עשו בחרן.** שהכניסן תחת כנפי השכינה, אברהם מגיר את האנשים, ושרה מגירת הנשים, ומעלה עליהם הכתוב כאלו עשאום. ופשוטו של מקרא עבדים ושפחות שקנו להם, כמו (שם לא א) עשה את כל הכבוד הזה, (במד' כד יח) וישראל עשה חיל, לשון קונה וכונס:
@6 **ויעבר אברם בארץ.** נכנס לתוכה: **עד מקום שכם.** להתפלל על בני יעקב כשיבאו להלחם בשכם: **אלון מורה.** הוא שכם, הראהו הר גריזים והר עיבל ששם קבלו ישראל שבועת התורה: **והכנעני אז בארץ.** היה הולך וכובש את ארץ ישראל מזרעו של שם, שבחלקו של שם נפלה כשחלק נח את הארץ לבניו, שנאמר (בראשית יד יח) ומלכי צדק מלך שלם, לפיכך (פסוק ז) ויאמר ה' אל אברם לזרעך אתן את הארץ הזאת, עתיד אני להחזירה לבניך שהם מזרעו של שם:
@7 **ויבן שם מזבח.** על בשורת הזרע ועל בשורת ארץ ישראל:
@8 **ויעתק משם.** אהלו: **מקדם לבית אל.** במזרחה של בית אל. נמצאת בית אל במערבו, והוא שנאמר בית אל מים: **אהלו.** אהלה כתיב, בתחלה נטה את אהל אשתו ואחר כך את שלו: **ויבן שם מזבח.** נתנבא שעתידין בניו להכשל שם על עון עכן והתפלל שם עליהם:
@9 **הלוך ונסוע.** לפרקים, יושב כאן חדש או יותר ונוסע משם ונוטה אהלו במקום אחר, וכל מסעיו הנגבה ללכת לדרומה של ארץ ישראל והוא לצד ירושלים שהיא בחלקו של יהודה, שנטלו בדרומה של ארץ ישראל הר המוריה שהיא נחלתו:
@10 **רעב בארץ.** באותה ארץ לבדה, לנסותו אם יהרהר אחר דבריו של הקדוש ברוך הוא שאמר לו ללכת אל ארץ כנען, ועכשיו משיאו לצאת ממנה:
@11 **הנה נא ידעתי.** מדרש אגדה עד עכשיו לא הכיר בה מתוך צניעות שבשניהם, ועכשיו על ידי מעשה הכיר בה. דבר אחר מנהג העולם שעל ידי טורח הדרך אדם מתבזה, וזאת עמדה ביפיה. ופשוטו של מקרא הנה נא הגיע השעה שיש לדאוג על יפיך, ידעתי זה ימים רבים כי יפת מראה את, ועכשיו אנו באים בין אנשים שחורים ומכוערים, אחיהם של כושים, ולא הרגלו באשה יפה. ודומה לו (בראשית יט ב) הנה נא אדני סורו נא:
@13 **למען ייטב לי בעבורך.** יתנו לי מתנות:
@14 **ויהי כבוא אברם מצרימה.** היה לו לומר כבואם מצרימה, אלא למד שהטמין אותה בתבה ועל ידי שתבעו את המכס פתחו וראו אותה:
@15 **ויהללו אותה אל פרעה.** הללוה ביניהם לומר הגונה זו למלך:
@16 **ולאברם היטיב.** פרעה **בעבורה.** [נתן לו מתנות]:
@17 **וינגע ה'** וגו' **.** במכת ראתן לקה, שהתשמיש קשה לו: **ואת ביתו.** כתרגומו ועל אנש ביתיה (ומדרשו לרבות כותליו ועמודיו וכליו) : **על דבר שרי.** על פי דבורה, אומרת למלאך הך והוא מכה:
@19 **קח ולך.** לא כאבימלך שאמר לו (כ טו) הנה ארצי לפניך, אלא אמר לו לך ואל תעמד, שהמצרים שטופי זמה הם, שנאמר (יחזקאל כג כ) וזרמת סוסים זרמתם:
@20 **ויצו עליו.** על אודותיו לשלחו ולשמרו: **וישלחו.** כתרגומו ואלויאו:
@21 **ויעל אברם** וגו' **הנגבה.** לבא לדרומה של ארץ ישראל כמו שאמור למעלה (פסוק ט) הלוך ונסוע הנגבה, להר המוריה, ומכל מקום כשהוא הולך ממצרים לארץ כנען מדרום לצפון הוא מהלך, שארץ מצרים בדרומה של ארץ ישראל, כמו שמוכיח במסעות ובגבולי הארץ:
@22 **כבד מאד.** טעון משאות:
@23 **וילך למסעיו.** כשחזר ממצרים לארץ כנען היה הולך ולן באכסניות שלן בהם בהליכתו למצרים. למדך דרך ארץ שלא ישנה אדם מאכסניא שלו. דבר אחר בחזרתו פרע הקפותיו: **מנגב.** ארץ מצרים בדרומה של ארץ כנען:
@24 **אשר עשה שם בראשנה ויקרא שם.** ואשר קרא שם אברם בשם ה'. וגם יש לומר ויקרא שם עכשיו בשם ה':
@25 **ההולך את אברם.** מי גרם שהיתה לו זאת, הליכתו עם אברם:
@26 **ולא נשא אתם.** לא היתה יכולה להספיק מרעה למקניהם, ולשון קצר הוא, וצריך להוסיף עליו, כמו ולא נשא אותם מרעה הארץ, לפיכך כתוב ולא נשא בלשון זכר:
@27 **ויהי ריב.** לפי שהיו רועים של לוט רשעים ומרעים בהמתם בשדות אחרים, ורועי אברם מוכיחים אותם על הגזל, והם אומרים נתנה הארץ לאברם, ולו אין יורש, ולוט יורשו, ואין זה גזל, והכתוב אומר והכנעני והפרזי אז ישב בארץ ולא זכה בה אברם עדיין:
@28 **אנשים אחים.** קרובים. ומדרש אגדה דומין בקלסתר פנים:
@29 **אם השמאל ואימנה.** בכל אשר תשב, לא אתרחק ממך ואעמוד לך למגן ולעזר. וסוף דבר הצרך לו שנאמר (יד יד) וישמע אברם כי נשבה אחיו וגו' : **ואימנה.** אימין את עצמי, כמו ואשמאילה אשמאיל את עצמי. ואם תאמר היה לו לנקד ואימינה, כך מצינו במקום אחר (ש''ב יד יט) אם אש להמין ואין נקוד להימין:
@30 **כי כלה משקה.** ארץ נחלי מים: **לפני שחת ה' את סדום ואת עמורה.** היה אותו מישור: **כגן ה'.** לאילנות: **כארץ מצרים.** לזרעים: **באכה צער.** עד צער. ומדרש אגדה דורשה לגנאי, על שהיו שטופי זמה בחר לו לוט בשכונתם במסכת הוריות (י ב) :
@31 **ככר.** מישור, כתרגומו: **מקדם.** נסע מאצל אברם והלך לו למערבו של אברם, נמצא נוסע ממזרח למערב. ומדרש אגדה הסיע עצמו מקדמונו של עולם אמר אי אפשי לא באברם ולא באלהיו:
@32 **ויאהל.** נטה אהלים לרועיו ולמקנהו עד סדום:
@33 **ואנשי סדום רעים.** ואף על פי כן לא נמנע לוט מלשכון עמהם. ורבותינו למדו מכאן (משלי י ז) שם רשעים ירקב: **רעים.** בגופם: **וחטאים.** בממונם: **לה' מאד.** יודעים רבונם ומתכונים למרוד בו:
@34 **אחרי הפרד לוט.** כל זמן שהרשע עמו היה הדבור פורש ממנו:
@36 **אשר אם יוכל איש.** כשם שאי אפשר לעפר להמנות, כך זרעך לא ימנה:
@38 **ממרא.** שם אדם:
@39 **אמרפל.** הוא נמרוד שאמר לאברהם פול לתוך כבשן האש: **מלך גוים.** מקום יש ששמו גוים, על שם שנתקבצו שמה מכמה אמות ומקומות והמליכו איש עליהם ושמו תדעל:
@40 **ברע.** רע לשמים ורע לבריות: **ברשע.** שנתעלה ברשעו: **שנאב.** שונא אביו שבשמים: **שמאבר.** שם אבר לעוף ולקפוץ ולמרוד בהקדוש ברוך הוא: **בלע.** שם העיר:
@41 **עמק השדים.** כך שמו, על שם שהיו בו שדות הרבה: **הוא ים המלח.** לאחר זמן נמשך הים לתוכו ונעשה ים המלח. ומדרש אגדה אומר שנתבקעו הצורים סביבותיו ונמשכו יאורים לתוכו:
@42 **שתים עשרה שנה עבדו.** חמשה מלכים הללו את כדרלעומר:
@43 **ובארבע עשרה שנה.** למרדן, **בא כדרלעומר' לפי שהוא היה בעל המעשה נכנס בעבי הקורה: והמלכים.** אלה שלשה מלכים: **הזוזים.** הם זמזמים:
@44 **בהררם.** בהר שלהם: **איל פארן.** כתרגומו מישור. ואומר אני שאין איל לשון מישור, אלא מישור של פארן איל שמו, ושל ממרא אלוני שמו, ושל ירדן ככר שמו, ושל שטים אבל שמו אבל השטים, וכן בעל גד בעל שמו, וכלם מתורגמין מישור, וכל אחד שמו עליו: **על המדבר.** אצל המדבר, כמו (במדבר ב כ) ועליו מטה מנשה:
@45 **עין משפט הוא קדש.** על שם העתיד, שעתידין משה ואהרן להשפט שם על עסקי אותו העין, והם מי מריבה. ואונקלוס תרגמו כפשוטו, מקום שהיו בני המדינה מתקבצים שם לכל משפט: **שדה העמלקי.** עדיין לא נלד עמלק ונקרא על שם העתיד: **בחצצון תמר.** הוא עין גדי, מקרא מלא (דה''י ב' כ ב) ביהושפט:
@47 **ארבעה מלכים את החמשה.** ואף על פי כן נצחו המועטים, להודיעך שגבורים היו, ואף על פי כן לא נמנע אברהם מלרדוף אחריהם:
@48 **בארת בארת חמר.** בארות הרבה היו שם שנוטלין משם אדמה לטיט של בנין. ומדרש אגדה שהיה הטיט מגבל בהם, ונעשה נס למלך סדום שיצא משם, לפי שהיו באמות מקצתן שלא היו מאמינין שנצל אברהם מאור כשדים מכבשן האש, וכיון שיצא זה מן החמר האמינו באברהם למפרע: **הרה נסו.** להר נסו. הרה כמו להר, כל תבה שצריכה למ''ד בתחלתה הטיל לה ה''א בסופה. ויש חלוק בין הרה לההרה שה''א שבסוף התבה עומדת במקום למ''ד שבראשה, אבל אינה עומדת במקום למ''ד ונקודה פת''ח תחתיה, והרי הרה כמו להר, או כמו אל הר, ואינו מפרש לאיזה הר, אלא שכל אחד נס כאשר מצא הר תחלה, וכשהוא נותן ה''א בראשה לכתוב ההרה או המדברה, פתרונו כמו אל ההר או כמו לההר, ומשמע לאותו הר הידוע ומפורש בפרשה:
@50 **והוא ישב בסדום.** מי גרם לו זאת, ישיבתו בסדום:
@51 **ויבא הפליט.** [מדרשו] לפי פשוטו זה עוג שפלט מן המלחמה, והוא שכתוב (דברים ג יא) כי רק עוג נשאר מיתר הרפאים, וזהו נשאר שלא הרגוהו אמרפל וחבריו כשהכו את הרפאים בעשתרות קרנים, תנחומא (חוקת כה) . ומדרש בראשית רבה (מב ח) זה עוג שפלט מדור המבול, וזהו מיתר הרפאים שנאמר (ו ד) הנפלים היו בארץ וגו' ומתכון שיהרג אברהם וישא את שרה: **העברי.** שבא מעבר הנהר: **בעלי ברית אברם.** שכרתו עמו ברית (דבר אחר שהשיאו לו עצה על המילה כמו שמפורש במקום אחר) :
@52 **וירק.** כתרגומו וזרז, וכן (ויקרא כו לג) והריקתי אחריכם חרב, אזדיין בחרבי עליכם, וכן (שמות טו ט) אריק חרבי, וכן (תהלים לה ג) והרק חנית וסגר: **חניכיו.** חנכו כתיב זה אליעזר שחנכו למצוות והוא לשון התחלת כניסת האדם או כלי לאמנות שהוא עתיד לעמוד בה, וכן (משלי כב ו) חנך לנער, (במדבר ז יא) חנכת המזבח, (תהלים ל א) חנכת הבית ובלע''ז קורין לו איניציי''ר : **שמנה עשר ושלש מאות.** רבותינו אמרו אליעזר לבדו היה, והוא מנין גימטריא של שמו: **עד דן.** שם תשש כחו, שראה שעתידין בניו להעמיד שם עגל:
@53 **ויחלק עליהם.** לפי פשוטו, סרס המקרא, ויחלק הוא ועבדיו עליהם לילה כדרך הרודפים שמתפלגים אחר הנרדפים כשבורחים זה לכאן וזה לכאן: **לילה.** כלומר אחר שחשכה לא נמנעו מלרדפם. ומדרש אגדה שנחלק הלילה ובחציו הראשון נעשה לו נס, וחציו השני נשמר ובא לו לחצות לילה של מצרים: **עד חובה.** אין מקום ששמו חובה, אלא דן קורא חובה על שם עבודה זרה שעתידה להיות שם:
@55 **עמק שוה.** כך שמו כתרגומו למישר מפנא, פנוי מאילנות ומכל מכשול: **עמק המלך.** בית ריסא דמלכא, בית ריס אחד שהוא שלשים קנים, שהיה מיוחד למלך לשחק שם. ומדרש אגדה עמק שהשוו שם כל האמות והמליכו את אברהם עליהם לנשיא אלהים ולקצין:
@56 **ומלכי צדק.** מדרש אגדה הוא שם בן נח: **לחם ויין.** כך עושים ליגיעי מלחמה, והראה לו שאין בלבו עליו על שהרג את בניו. ומדרש אגדה רמז לו על המנחות ועל הנסכים שיקריבו שם בניו:
@57 **קנה שמים וארץ.** כמו (תהלים קלד ג) עשה שמים וארץ, על ידי עשיתן קנאן להיות שלו:
@58 **אשר מגן.** אשר הסגיר, וכן (הושע יא ח) אמגנך ישראל: **ויתן לו.** אברם, מעשר מכל אשר לו לפי שהיה כהן:
@59 **תן לי הנפש.** מן השבי שלי שהצלת, החזר לי הגופים לבדם:
@60 **הרימתי ידי.** לשון שבועה, מרים אני את ידי לאל עליון וכן (בראשית כב טז) בי נשבעתי, נשבע אני, וכן (שם כג יג) נתתי כסף השדה קח ממני, נותן אני לך כסף השדה וקחהו ממני:
@61 **אם מחוט ועד שרוך נעל.** אעכב לעצמי מן השבי: **ואם אקח מכל אשר לך.** ואם תאמר לתת לי שכר מבית גנזיך, לא אקח: **ולא תאמר אני העשרתי את אברם.** שהקדוש ברוך הוא הבטיחני לעשרני, שנאמר לעיל (יב ב) ואברכך וגו' :
@62 **הנערים.** עבדי אשר הלכו אתי, ועוד ענר אשכל וממרא וגו' . ואף על פי שעבדי נכנסו למלחמה, שנאמר לעיל (פסוק טו) הוא ועבדיו ויכם, וענר וחבריו ישבו על הכלים לשמר, אפלו הכי הם יקחו חלקם. וממנו למד דוד שאמר (ש''א ל כד) כחלק הירד למלחמה וכחלק הישב על הכלים יחדו יחלקו. לכך נאמר (שם פסוק כה) ויהי מהיום ההוא ומעלה וישמה לחק ולמשפט, ולא נאמר והלאה לפי שכבר נתן החוק בימי אברהם:
@63 **אחר הדברים האלה.** כל מקום שנאמר אחר סמוך, אחרי מפלג. אחר שנעשה לו נס זה שהרג את המלכים והיה דואג ואומר שמא קבלתי שכר על כל צדקתי, לכך אמר לו המקום אל תירא אברם אנכי מגן לך מן הענש שלא תענש על כל אותן נפשות שהרגת, ומה שאתה דואג על קבול שכרך, שכרך הרבה מאד:
@64 **הולך ערירי.** מנחם בן סרוק פרשו לשון יורש, וחבר לו (מלאכי ב יב) ער וענה, ערירי בלא יורש, כאשר תאמר (איוב לא יב) ובכל תבואתי תשרש, תעקר שרשיה, כך לשון ערירי חסר בנים, ובלע''ז דישאנפנטי''ף . ולי נראה ער וענה מגזרת (שיר השירים ה ב) ולבי ער, וערירי לשון חרבן, וכן (תהל' קלז ז) ערו ערו, וכן (חבק' ג יג) ערות יסוד, וכן (ירמיה נא נח) ערער תתערער, וכן (צפניה ב יד) כי ארזה ערה: **ובן משק ביתי.** כתרגומו, שכל ביתי נזון על פיו, כמו (בראשית מא מ) ועל פיך ישק, אפטורפס שלי, ואלו היה לי בן היה בני ממנה על שלי: **דמשק.** לפי התרגום מדמשק היה, ולפי מדרש אגדה שרדף המלכים עד דמשק. ובתלמוד דרשו נוטריקון דולה ומשקה מתורת רבו לאחרים:
@65 **הן לי לא נתת זרע.** ומה תועלת בכל אשר תתן לי:
@67 **ויוצא אתו החוצה.** לפי פשוטו הוציאו מאהלו לחוץ לראות הכוכבים, ולפי מדרשו אמר לו צא מאצטגנינות שלך שראית במזלות שאינך עתיד להעמיד בן, אברם אין לו בן, אבל אברהם יש לו בן. וכן שרי לא תלד, אבל שרה תלד, אני קורא לכם שם אחר וישתנה המזל. דבר אחר הוציאו מחללו של עולם והגביהו למעלה מן הכוכבים, וזהו לשון הבטה מלמעלה למטה:
@68 **והאמין בה'.** לא שאל לו אות על זאת, אבל על ירשת הארץ שאל לו אות ואמר לו במה אדע: **ויחשבה לו צדקה.** הקדוש ברוך הוא חשבה לאברם לזכות ולצדקה על האמונה שהאמין בו. דבר אחר במה אדע, לא שאל לו אות אלא אמר לפניו הודיעני באיזה זכות יתקימו בה, אמר לו הקדוש ברוך הוא בזכות הקרבנות:
@71 **עגלה משלשת.** שלשה עגלים, רמז לשלשה פרים פר יום הכפורים, ופר העלם דבר של צבור, ועגלה ערופה: **ועז משלשת.** רמז לשעיר הנעשה בפנים, ושעירי מוספין של מועד, ושעיר חטאת יחיד: **ואיל משלש.** אשם ודאי, ואשם תלוי, וכבשה של חטאת יחיד: **ותור וגוזל.** תור ובן יונה:
@72 **ויבתר אתם.** חלק כל אחד לשני חלקים, ואין המקרא יוצא מידי פשוטו לפי שהיה כורת עמו ברית לשמור הבטחתו להוריש לבניו את הארץ, כדכתיב (פסוק יח) ביום ההוא כרת ה' את אברם ברית לאמר וגו' , ודרך כורתי ברית לחלק בהמה ולעבר בין בתריה, כמה שנאמר להלן (ירמיה לד יט) העוברים בין בתרי העגל, אף כאן תנור עשן ולפיד אש אשר עבר בין הגזרים הוא שלוחו של שכינה שהוא אש: **ואת הצפור לא בתר.** לפי שהאמות נמשלו לפרים ואילים ושעירים, שנאמר (תהלים כב יג) סבבוני פרים רבים וגו' , ואומר (דניאל ח כ) והאיל אשר ראית בעל הקרנים מלכי מדי ופרס. ואומר (שם כא) והצפיר השעיר מלך יון, וישראל נמשלו לבני יונה שנאמר (שה''ש ב יד) יונתי בחגוי הסלע, לפיכך בתר הבהמות רמז על האמות שיהיו כלין והולכין, ואת הצפור לא בתר רמז שיהיו ישראל קימין לעולם:
@73 **העיט.** הוא עוף, ועל שם שהוא עט ושואף הנבלות (איוב ט כו) לטוש עלי אכל, כמו (שמואל א' טו יט) ותעט אל השלל: **על הפגרים.** על הבתרים (הפגרים מתרגמינן פגליא, אלא מתוך שהרגלו לתרגם (פסוק י) איש בתרו, ויהב פלגיא, נתחלף להם תבת פגליא לפלגיא, ותרגמו הפגרים פלגיא, וכל המתרגם כן טועה, לפי שאין להקיש בתרים לפגרים, שבתרים תרגומו פלגיא, ופגרים תרגומו פגליא לשון פגול, כמו (ויקרא יט ז) פגול הוא לשון פגר) : **וישב.** לשון נשיבה והפרחה, כמו (תהל' קמז יח) ישב רוחו, רמז שיבא דוד בן ישי לכלותם, ואין מניחין אותו מן השמים עד שיבא מלך המשיח:
@74 **והנה אימה** וגו' **.** רמז לצרות וחשך של גליות:
@75 **כי גר יהיה זרעך.** משנלד יצחק עד שיצאו ישראל ממצרים ארבע מאות שנה. כיצד, יצחק בן ששים שנה כשנלד יעקב. ויעקב כשירד למצרים אמר (להלן מז ט) ימי שני מגורי שלשים ומאת שנה, הרי מאה ותשעים, ובמצרים היו מאתים ועשר כמנין רדו, הרי ארבע מאות שנה. ואם תאמר במצרים היו ארבע מאות, הרי קהת מיורדי מצרים היה, צא וחשוב שנותיו של קהת, ושל עמרם, ושמונים של משה שהיה כשיצאו ישראל ממצרים, אין אתה מוצא אלא שלש מאות וחמשים, ואתה צריך להוציא מהן כל השנים שחי קהת אחר לידת עמרם, ושחי עמרם אחר לידת משה: **בארץ לא להם.** לא נאמר בארץ מצרים אלא בארץ לא להם, ומשנלד יצחק (להלן כא לד) ויגר אברהם וגו' , וביצחק (שם כו ג) גור בארץ הזאת, (תהלים קה כג) ויעקב גר בארץ חם, (בראשית מז ד) לגור בארץ באנו:
@76 **וגם את הגוי.** וגם לרבות ארבע מלכיות, שאף הם כלים על ששעבדו את ישראל: **דן אנכי.** בעשר מכות: **ברכוש גדול.** בממון גדול, כמו שנאמר (שמות יב לו) וינצלו את מצרים:
@77 **ואתה תבוא.** ולא תראה כל אלה: **אל אבתיך.** אביו עובד עבודה זרה והוא מבשרו שיבא אליו, אלא למדך שעשה תרח תשובה: **תקבר בשיבה טובה.** בשרו שיעשה ישמעאל תשובה בימיו ולא יצא עשו לתרבות רעה בימיו, ולפיכך מת חמש שנים קודם זמנו ובו ביום מרד עשו:
@78 **ודור רביעי.** לאחר שיגלו למצרים יהיו שם שלשה דורות, והרביעי ישובו לארץ הזאת, לפי שבארץ כנען היה מדבר עמו וכרת ברית זו, כדכתיב (פסוק ז) לתת לך את הארץ הזאת לרשתה, וכן היה. יעקב ירד למצרים. צא וחשוב דורותיו יהודה, פרץ, חצרון, וכלב בן חצרון מבאי הארץ היה: **כי לא שלם עון האמורי.** להיות משתלח מארצו עד אותו זמן, שאין הקדוש ברוך הוא נפרע מאמה עד שתתמלא סאתה, שנאמר (ישעיה כז ח) בסאסאה בשלחה תריבנה:
@79 **ויהי השמש באה.** כמו ויהי הם מריקים שקיהם (בראשית מב לה) , ויהי הם קוברים איש, כלומר ויהי דבר זה (מ''ב יג כא) : **השמש באה.** שקעה: **ועלטה היה.** חשך היום: **והנה תנור עשן** וגו' **.** רמז לו שיפלו המלכיות בגיהנם. באה טעמו למעלה, לכך הוא מבואר שבאה כבר, ואם היה טעמו למטה באל''ף היה מבואר כשהיא שוקעת. ואי אפשר לומר כן, שהרי כבר כתיב ויהי השמש לבא, והעברת תנור עשן לאחר מכאן היתה נמצא שכבר שקעה. וזה חלוק בכל תבה לשון נקבה שיסודה שתי אותיות, כמו בא, קם, שב, כשהטעם למעלה, לשון עבר הוא, כגון זה, וכגון (להלן כט ט) ורחל באה, (שם לז ז) קמה אלמתי, (רות א טו) הנה שבה יבמתך, וכשהטעם למטה הוא לשון הוה, דבר שנעשה עכשיו והולך, כמו (להלן כט ו) באה עם הצאן, (אסתר ב יד) בערב היא באה ובבקר היא שבה:
@80 **לזרעך נתתי.** אמירתו של הקדוש ברוך הוא כאלו היא עשויה: **הנהר הגדול נהר פרת.** לפי שהוא דבוק לארץ ישראל קראהו גדול אף על פי שהוא מאוחר בארבעה נהרות היוצאים מעדן, שנאמר והנהר הרביעי הוא פרת. משל הדיוט עבד מלך מלך, הדבק לשחור וישתחוו לך:
@81 **את הקיני.** עשר אמות יש כאן ולא נתן להם אלא שבעה גוים, והשלשה אדום ומואב ועמון, והם קיני קניזי וקדמוני עתידים להיות ירשה לעתיד, שנאמר (ישעיה יא יד) אדום ומואב משלוח ידם ובני עמון משמעתם:
@82 **ואת הרפאים.** ארץ עוג, שנאמר בה (דברים ג יג) ההוא יקרא ארץ רפאים:
@84 **שפחה מצרית.** בת פרעה היתה, כשראה נסים שנעשו לשרה אמר מוטב שתהא בתי שפחה בבית זה ולא גבירה בבית אחר:
@85 **אולי אבנה ממנה.** למד על מי שאין לו בנים שאינו בנוי אלא הרוס: **אבנה ממנה.** בזכות שאכניס צרתי לתוך ביתי: **לקול שרי.** לרוח הקודש שבה:
@86 **ותקח שרי.** לקחתה בדברים אשריך שזכית לדבק בגוף קדוש כזה: **מקץ עשר שנים.** מועד הקבוע לאשה ששהתה עשר שנים ולא ילדה לבעלה חיב לשא אחרת: **לשבת אברם** וגו' **.** מגיד שאין ישיבת חוצה לארץ עולה לו מן המנין, לפי שלא נאמר לו (לעיל יב ב) ואעשך לגוי גדול, עד שיבא לארץ ישראל:
@87 **ויבא אל הגר ותהר.** מביאה ראשונה: **ותקל גברתה בעיניה.** אמרה שרי זו אין סתרה כגלויה, מראה עצמה כאלו היא צדקת ואינה צדקת, שלא זכתה להריון כל השנים הללו, ואני נתעברתי מביאה ראשונה:
@88 **חמסי עליך.** חמס העשוי לי, עליך אני מטילה הענש, כשהתפללת להקדוש ברוך הוא מה תתן לי ואנכי הולך ערירי, לא התפללת אלא עליך, והיה לך להתפלל על שנינו והייתי אני נפקדת עמך. ועוד, דבריך אתה חומס ממני שאתה שומע בזיוני ושותק: **אנכי נתתי שפחתי** וגו' **ביני וביניך.** כל ביני ובינך שבמקרא חסר, וזה מלא, קרי ביה וביניך שהכניסה עין הרע בעבורה של הגר והפילה עברה, הוא שהמלאך אומר להגר הנך הרה, והלא כבר הרתה והוא מבשר לה שתהר, אלא מלמד שהפילה הריון הראשון:
@89 **ותענה שרי.** היתה משעבדת בה בקושי:
@91 **אי מזה באת.** מהיכן באת. יודע היה, אלא לתן לה פתח לכנס עמה בדברים. ולשון אי מזה, איה המקום שתאמר עליו מזה אני באה:
@92 **ויאמר לה מלאך ה'** וגו' **.** על כל אמירה היה שלוח לה מלאך אחר, לכך נאמר מלאך בכל אמירה ואמירה:
@94 **הנך הרה.** כשתשובי תהרי, כמו (שופטים יג ז) הנך הרה, דאשת מנוח: **וילדת בן.** כמו ויולדת, ודומה לו (ירמיה כב כג) ישבת בלבנון מקננת בארזים: **וקראת שמו.** צווי הוא, כמו שאומר לזכר (יז יט) וקראת את שמו יצחק:
@95 **פרא אדם.** אוהב מדברות לצוד חיות, כמו שכתוב (כא כ. כא) ויהי רבה קשת וישב במדבר פארן: **ידו בכל.** לסטים: **ויד כל בו.** הכל שונאין אותו ומתגרין בו: **ועל פני כל אחיו ישכן.** שיהיה זרעו גדול:
@96 **אתה אל ראי.** נקוד חטף קמ''ץ מפני שהוא שם דבר, אלוה הראיה, שרואה בעלבון של עלובין: **הגם הלם.** לשון תימה, וכי סבורה הייתי שאף הלום במדברות ראיתי שלוחו של מקום אחרי רואי אותם בביתו של אברהם, ששם הייתי רגילה לראות מלאכים. ותדע שהיתה רגילה לראותם שהרי מנוח ראה את המלאך פעם אחת ואמר (שופטים יג כב) מות נמות, וזו ראתה ארבעה פעמים זה אחר זה ולא חרדה:
@97 **באר לחי ראי.** כתרגומו בירא דמלאך קיימאאתחזי עלה:
@98 **ויקרא אברם שם** וגו' **.** אף על פי שלא שמע אברם דברי המלאך שאמר (פסוק יא) וקראת שמו ישמעאל, שרתה רוח הקדש עליו וקראו ישמעאל:
@99 **ואברם בן שמנים שנה** וגו' **.** לשבחו של ישמעאל נכתב, להודיע שהיה בן שלש עשרה שנה כשנמול ולא עכב:
@100 **אני אל שדי.** אני הוא שיש די באלהותי לכל בריה, לפיכך התהלך לפני ואהיה לך לאלוה ולפטרון, וכן כל מקום שהוא במקרא פרושו די יש לו, והכל לפי הענין: **התהלך לפני.** כתרגומו פלח קדמי, הדבק בעבודתי: **והיה תמים.** אף זה צווי אחר צווי, היה שלם בכל נסיונותי. ולפי מדרשו התהלך לפני במצות מילה, ובדבר הזה תהיה תמים, שכל זמן שהערלה בך אתה בעל מום לפני. דבר אחר והיה תמים, עכשיו אתה חסר חמשה אברים שתי עינים, שתי אזנים, וראש הגויה שאוסיף לך אות על שמך ויהיו מנין אותיותיך מאתים ארבעים ושמונה כמנין אבריך:
@101 **ואתנה בריתי.** ברית של אהבה וברית הארץ להורישה לך על ידי מצוה זו:
@102 **ויפל אברם על פניו.** ממורא השכינה, שעד שלא מל לא היה בו כח לעמוד ורוח הקדש נצבת עליו, וזהו שנאמר בבלעם (במדבר כד ד) נפל וגלוי עינים. בברייתא דרבי אליעזר מצאתי כן:
@104 **כי אב המון גוים.** לשון נוטריקון של שמו. ורי''ש שהיתה בו בתחלה, שלא היה אב אלא לארם שהוא מקומו ועכשיו אב לכל העולם, לא זזה ממקומה, שאף יו''ד של שרי נתרעמה על השכינה עד שנתוספה ליהושע, שנאמר (במדבר יג טז) ויקרא משה להושע בן נון יהושע:
@105 **ונתתיך לגוים.** ישראל ואדום, שהרי ישמעאל כבר היה לו ולא היה מבשרו עליו:
@106 **והקמתי את בריתי.** ומה היא הברית, להיות לך לאלהים:
@107 **לאחזת עולם.** ושם אהיה להם לאלהים, אבל הדר בחוצה לארץ דומה כמי שאין לו אלוה:
@108 **ואתה.** וא''ו זו מוסיף על ענין ראשון אני הנה בריתי אתך, ואתה הוי זהיר לשמרו, ומה היא שמירתו, (פסוק י) זאת בריתי אשר תשמרו המול לכם וגו' :
@109 **ביני וביניכם** וגו' **.** אותם של עכשיו: **ובין זרעך אחריך.** העתידין להולד: **המול.** כמו להמול כמו שאתה אומר עשות, כמו לעשות:
@110 **ונמלתם.** כמו ומלתם והנו''ן בו יתרה ליסוד הנופל בו לפרקים, כגון נ' של נושך ונ' של נושא. ונמלתם, כמו ונשאתם, אבל ימול לשון יפעל כמו יעשה, יאכל:
@111 **יליד בית.** שילדתו השפחה בבית: **ומקנת כסף.** שקנאו משנלד:
@112 **המול ימול יליד ביתך.** כאן כפל עליו ולא אמר לשמונה ימים, ללמדך שיש יליד בית נמול לאחר שמנה ימים, כמו שמפורש במסכת שבת (דף קלח ב) :
@113 **וערל זכר.** כאן למד שהמילה באותו מקום שהוא נכר בין זכר לנקבה: **אשר לא ימול.** משיגיע לכלל ענשין ונכרתה, אבל אביו אין ענוש עליו כרת אבל עובר בעשה: **ונכרתה הנפש.** הולך ערירי ומת קודם זמנו:
@114 **לא תקרא את שמה שרי.** דמשמע שרי לי ולא לאחרים כי שרה סתם שמה, שתהא שרה על כל:
@115 **וברכתי אתה.** ומה היא הברכה, שחזרה לנערותה, שנאמר (לקמן יח יב) אחרי בלתי היתה לי עדנה: **וברכתיה.** בהנקת שדים, כשנצרכה לכך ביום משתה של יצחק, שהיו מרננים עליהם שהביאו אסופי מן השוק ואומרים בננו הוא, והביאה כל אחת בנה עמה ומניקתה לא הביאה, והיא היניקה את כלם, הוא שנאמר (כא ז) היניקה בנים שרה. בראשית רבה (נג ט) רמזו במקצת:
@116 **ויפל אברהם על פניו ויצחק.** זה תירגם אנקלוס וחדי, לשון שמחה, ושל שרה לשון מחוך. למדת שאברהם האמין ושמח, ושרה לא האמינה ולגלגה. וזהו שהקפיד הקדוש ברוך הוא על שרה ולא הקפיד על אברהם: **הלבן.** יש תמיהות שהן קימות כמו (ש''א ב כז) הנגלה נגליתי, (ש''ב טו כז) הראה אתה, אף זו היא קימת, וכך אמר בלבו הנעשה חסד זה לאחר מה שהקדוש ברוך הוא עושה לי: **ואם שרה הבת תשעים שנה.** היתה כדאי לילד. ואף על פי שדורות הראשונים היו מולידין בני חמש מאות שנה, בימי אברהם נתמעטו השנים כבר ובא תשות כח לעולם, וצא ולמד מעשרה דורות שמנח ועד אברהם שמיהרו תולדותיהן בני ששים ובני שבעים:
@117 **לו ישמעאל יחיה.** הלואי שיחיה ישמעאל, איני כדאי לקבל מתן שכר כזה: **יחיה לפניך.** יחיה ביראתך, כמו (פסוק א) התהלך לפני, פלח קדמי:
@118 **אבל.** לשון אמתת דברים, וכן (לקמן מב כא) אבל אשמים אנחנו, (מ''ב ד יד) אבל בן אין לה: **וקראת את שמו יצחק.** על שם הצחוק. ויש אומרים על שם י' נסיונות, וצ' שנה של שרה, וח' ימים שנמול, וק' שנה של אברהם. והקימתי את בריתי למה נאמר, והרי כבר כתיב (פסוק ט) ואתה את בריתי תשמור אתה וזרעך וגו' אלא לפי שאומר (פסוק ז) והקמתי וגו' , יכול בני ישמעאל ובני קטורה בכלל הקיום, תלמוד לומר והקמותי את בריתי אתו, ולא עם אחרים. ואת בריתי אקים את יצחק, למה נאמר, [אלא למד שהיה קדוש מבטן]. דבר אחר אמר ר' אבא מכאן למד קל וחומר בן הגבירה מבן האמה, כתיב (פסוק כ) כי הנה ברכתי אותו והפריתי אותו והרביתי אותו, זה ישמעאל וקל וחמר ואת בריתי אקים את יצחק: **את בריתי.** ברית המילה תהא מסורה לזרעו של יצחק:
@119 **שנים עשר נשיאם.** כעננים יכלו, כמו (משלי כה יד) נשיאים ורוח:
@121 **מעל אברהם.** לשון נקיה הוא כלפי שכינה, ולמדנו שהצדיקים מרכבתו של מקום:
@122 **בעצם היום.** בו ביום שנצטוה, ביום ולא בלילה, לא נתיירא לא מן הגוים ולא מן הלצנים, ושלא יהיו אויביו ובני דורו אומרים אלו ראינוהו לא הנחנוהו למול ולקים מצותו של מקום: **וימל.** לשון ויפעל:
@123 **בהמלו.** בהפעלו, כמו (ב ד) בהבראם:
@124 **בהמלו את בשר ערלתו.** באברהם לא נאמר את, לפי שלא היה חסר אלא חתוך בשר, שכבר נתמעך על ידי תשמיש, אבל ישמעאל שהיה ילד הוזקק לחתוך ערלה ולפרוע המילה, לכך נאמר בו את:
@125 **בעצם היום הזה.** שמלאו לאברהם תשעים ותשע שנה ולישמעאל שלש עשרה שנים נמול אברהם וישמעאל בנו:

@1 **ויאמר ה' אל אברם לך לך** . להנאתך ולטובתך ושם אעשך לגוי גדול וכאן אי אתה זוכה לבנים לשון רש"י ואין צורך כי משפט הלשון כן הגשם חלף הלך לו (שיר השירים ב יא) אלכה לי אל הגדולים (ירמיהו ה ה) קומו ועברו לכם את נחל זרד (דברים ב יג) ורובם ככה אבל רבותינו (יומא ג עב) עשו מדרש במה שאמר הכתוב (דברים י א) ועשית לך ארון עץ ועשה לך שתי חצוצרות כסף (במדבר י ב) בעבור שאין המלאכה שלו והיה ראוי שיאמר כמו שאמר במשכן ואת המשכן תעשה (שמות כו א)
@1 "מארצך וממולדתך" - כתב רש"י והלא כבר יצא משם עם אביו ובא עד חרן אלא כך אמר לו הקב"ה התרחק עוד מבית אביך ורבי אברהם פירש וכבר אמר השם אל אברם לך לך מארצך כי הדבור הזה היה בעודנו באור כשדים ושם צוהו לעזוב ארצו ומולדתו ובית אביו אשר שם ואיננו נכון כי אם היה כן היה אברם עיקר הנסיעה מבית אביו במצות האלהים ותרח אביו ברצון נפשו הלך עמו והכתוב אמר (לעיל יא לא) ויקח תרח את אברם בנו יורה כי אברם אחרי אביו ובעצתו יצא מאור כשדים ללכת ארצה כנען ועוד כי הכתוב שאמר (יהושע כד ג) ואקח את אביכם את אברהם מעבר הנהר ואולך אותו בכל ארץ כנען היה ראוי שיאמר "ואקח את אביכם את אברהם מאור כשדים ואולך אותו בכל ארץ כנען" כי משם לוקח ושם נצטוה בזה ועוד יקשה עליהם כי אברהם בצוותו את אליעזר לקחת אשה לבנו אמר לו כי אל ארצי ואל מולדתי תלך (להלן כד ד) והוא הלך אל ארם נהרים אל עיר נחור (שם כד י) אם כן היא ארצו ומולדתו ושם נאמר (בפסוק לח) אם לא אל בית אבי תלך ואל משפחתי כי שם בית אביו ומשפחתו שהיא מולדתו לא כאשר השתבש רבי אברהם לומר אל ארצי חרן ומולדתי אור כשדים והנה הוא האומר כאן כי באור כשדים נאמר לו לך לך מארצך וממולדתך ומבית אביך והנה לו ארצות רבות אבל העיקר כבר ידעת אותו ממה שכתבנו בסדר שלפני זה (יא כח) כי חרן היא ארצו ושם מולדתו והיא ארץ אבותיו מעולם ושם נצטוה לעזוב אותם וכך אמרו בבראשית רבה (לט ח) לך לך אחת מארם נהרים ואחת מארם נחור וטעם להזכיר "ארצך ומולדתך ובית אביך" כי יקשה על האדם לעזוב ארצו אשר הוא יושב בה ושם אוהביו ורעיו וכל שכן כשהוא ארץ מולדתו ששם נולד וכל שכן כשיש שם כל בית אביו ולכך הוצרך לומר לו שיעזוב הכל לאהבתו של הקב"ה
@1 "אל הארץ אשר אראך" - היה נודד והולך מגוי אל גוי ומממלכה אל עם אחר עד שבא אל ארץ כנען ואמר לו לזרעך אתן את הארץ הזאת אז נתקיים "אל הארץ אשר אראך" ואז נתעכב וישב בה ומה שאמר ויצאו ללכת ארצה כנען לא להתישב בה כי עדיין לא ידע כי על הארץ ההיא נצטוה אלא שאחז צדיק דרכו דרך ארץ כנען כי כן היה בדעתו ובדעת אביו גם מתחלה בצאתם מאור כשדים ומפני זה אמר ויהי כאשר התעו אותי אלהים מבית אבי (להלן כ יג) כי היה תועה כשה אובד ויתכן לומר כי אברהם מבראשונה ידע כי ארץ כנען היא נחלת ה' ובה יתן ה' חלקו והאמין כי "אל הארץ אשר אראך" ירמוז לו על ארץ כנען או על כולה או על אחת מכל הארצות האל ושם פניו אל כלל ארץ כנען כי שם הארץ אשר יראנו באמת
@2 **והיה ברכה** . אתה תהיה הברכה אשר יתברכו בך לאמר "ישימך אלהים כאברהם" והוסיף עוד כי כל משפחות האדמה יתברכו בו לא אנשי ארצו בלבד או ונברכו בך שיהיו מבורכים בעבורו והנה זאת הפרשה לא בארה כל הענין כי מה טעם שיאמר לו הקב"ה עזוב ארצך ואיטיבה עמך טובה שלא היתה כמוהו בעולם מבלי שיקדים שהיה אברהם עובד אלהים או צדיק תמים או שיאמר טעם לעזיבת הארץ שיהיה בהליכתו אל ארץ אחרת קרבת אלהים ומנהג הכתוב לאמר התהלך לפני ותשמע בקולי ואיטיבה עמך כאשר בדוד ובשלמה וכענין התורה כולה אם בחוקותי תלכו (ויקרא כו ג) אם שמע תשמע בקול ה' אלהיך (דברים כח א) וביצחק אמר בעבור אברהם עבדי (להלן כו כד) אבל להבטיחו בעבור יציאת הארץ אין בו טעם אבל הטעם מפני שעשו אנשי אור כשדים עמו רעות רבות על אמונתו בהקב"ה והוא ברח מהם ללכת ארצה כנען ונתעכב בחרן אמר לו לעזוב גם אלו ולעשות כאשר חשב מתחלה שתהיה עבודתו לו וקריאת בני האדם לשם ה' בארץ הנבחרת ושם יגדל שמו ויתברכו בו הגוים ההם לא כאשר עשו עמו באור כשדים שהיו מבזין ומקללים אותו ושמו אותו בבור או בכבשן האש ואמר לו שיברך מברכיו ואם יחיד מקללו יואר וזה טעם הפרשה אבל התורה לא תרצה להאריך בדעות עובדי עבודה זרה ולפרש הענין שהיה בינו ובין הכשדים באמונה כאשר קצרה בענין דור אנוש וסברתם בעבודה זרה שחדשו
@6 **ויעבר אברם בארץ עד מקום שכם** . אומר לך כלל תבין אותו בכל הפרשיות הבאות בענין אברהם יצחק ויעקב והוא ענין גדול הזכירוהו רבותינו בדרך קצרה ואמרו (תנחומא ט) כל מה שאירע לאבות סימן לבנים ולכן יאריכו הכתובים בספור המסעות וחפירת הבארות ושאר המקרים ויחשוב החושב בהם כאלו הם דברים מיותרים אין בהם תועלת וכולם באים ללמד על העתיד כי כאשר יבוא המקרה לנביא משלשת האבות יתבונן ממנו הדבר הנגזר לבא לזרעו ודע כי כל גזירת עירין כאשר תצא מכח גזירה אל פועל דמיון תהיה הגזרה מתקיימת על כל פנים ולכן יעשו הנביאים מעשה בנבואות כמאמר ירמיהו שצוה לברוך והיה ככלותך לקרוא את דברי הספר הזה תקשור עליו אבן והשלכתו אל תוך פרת ואמרת ככה תשקע בבל וגו' (ירמיה נא סג סד) וכן ענין אלישע בהניחו זרועו על הקשת (מלכים ב יג טז-יז) ויאמר אלישע ירה ויור ויאמר חץ תשועה לה' וחץ תשועה בארם ונאמר שם (פסוק יט) ויקצוף עליו איש האלהים ויאמר להכות חמש או שש פעמים אז הכית את ארם עד כלה ועתה שלש פעמים תכה את ארם ולפיכך החזיק הקב"ה את אברהם בארץ ועשה לו דמיונות בכל העתיד להעשות בזרעו והבן זה ואני מתחיל לפרש הענינים בפרט בפסוקים בעזרת השם
@6 "ויעבור אברם בארץ עד מקום שכם" - היא עיר שכם כן זה שם המקום ההוא ושכם בן חמור על שם עירו נקרא וכתב רש"י נכנס לתוכה עד מקום שכם להתפלל על בני יעקב כשיבואו מן השדה עצבים ונכון הוא ואני מוסיף כי החזיק אברהם במקום ההוא תחלה וקודם שנתן לו את הארץ נרמז לו מזה כי בניו יכבשו המקום ההוא תחלה קודם היותם זוכים בו וקודם היות עון יושב הארץ שלם להגלותם משם ולכן אמר והכנעני אז בארץ וכאשר נתן לו הקב"ה הארץ במאמר אז נסע משם ונטע אהל בין בית אל ובין העי כי הוא המקום אשר כבש יהושע בתחלה ויתכן שהזכיר הכתוב והכנעני אז בארץ להורות על ענין הפרשה לומר כי אברם בא בארץ כנען ולא הראהו השם הארץ אשר יעדו ועבר עד מקום שכם והכנעני הגוי המר והנמהר אז בארץ ואברם ירא ממנו ולכן לא בנה מזבח לה' ובבואו במקום שכם באלון מורה נראה אליו השם ונתן לו הארץ וסרה יראתו כי כבר הובטח בארץ אשר אראך ואז בנה מזבח לה' לעבדו בפרהסיא
@6 "ואלון מורה" - זהו במקום שכם ונקרא גם כן "אלוני מורה" כמו שכתוב (דברים יא ל) מול הגלגל אצל אלוני מורה ושם הר גריזים והר עבל בשכם וקרוב לירדן שבאו שם בתחילת ביאתם בארץ אבל "אלוני ממרא" הוא מקום אשר הוא בארץ חברון רחוק מן הירדן ודע כי בכל מקום שיאמר הכתוב "אלוני ממרא" שם "ממרא" הוא על איש אמורי שהמקום ההוא שלו כמו שנאמר (להלן יד יג) והוא שוכן באלוני ממרא האמורי אחי אשכול ואחי ענר וכל "אלון מורה" ו"אלוני מורה" נקרא המקום ההוא על שם איש ששמו "מורה" אבל זה כנעני הוא מארץ הכנעני היושב בערבה וכשיזכיר הכתוב ממרא סתם הוא שם העיר כמו שנאמר (להלן לה כז) ויבא יעקב אל יצחק אביו ממרא קרית הארבע היא חברון על פני ממרא היא חברון (להלן כג יט) כי האיש אשר לו אלוני נקרא על שם העיר וכן שכם בן חמור כשם העיר שכם ובבראשית רבה (מב ח) על דעתיה דרבי יהודה אתרא הוא דשמיה ממרא ועל דעתיה דרבי נחמיה גברא הוא דשמיה ממרא
@7 **וטעם לה' הנראה אליו** . כי הודה לשם הנכבד וזבח לו זבח תודה על שנראה אליו כי עד הנה לא נראה אליו השם ולא נתודע אליו במראה ולא במחזה אבל נאמר לו "לך לך מארצך" בחלום הלילה או ברוח הקדש ויתכן שירמוז "הנראה אליו" על סוד הקרבן (עיין רקאנטי כא ב) והמשכיל יבין
@8 **ויקרא בשם ה'** . פירש אונקלוס שהתפלל שם כמו קראתי שמך ה' מבור תחתיות (איכה ג נה) והנכון שהיה קורא בקול גדול שם לפני המזבח את שם ה' מודיע אותו ואלהותו לבני אדם כי באור כשדים היה מלמדם ולא אבו שמוע ועתה כשבא בארץ הזאת שהובטח בה "ואברכה מברכיך" היה למוד ללמד ולפרסם האלהות וכן אמר הכתוב (להלן כו כד) ביצחק כאשר הלך אל נחל גרר והובטח אל תירא כי אתך אנכי שבנה מזבח "ויקרא בשם ה'" כי בא במקום חדש אשר לא שמעו את שמעו ולא ראו את כבודו והגיד כבודו בגוים ההם ולא נאמר ביעקב כן מפני שהוליד בנים רבים כלם עובדי ה' והיתה לו קהלה גדולה נקראת עדת ישראל ונתפרסמה האמונה בהם ונודעה לכל עם וגם כי מימי אבותיו נתפרסמה בכל ארץ כנען וכך אמרו בבראשית רבה (לט טז) מלמד שהקריא שמו של הקב"ה בפי כל בריה
@9 **הנגבה** . כתב רבינו שלמה ללכת לדרומה של ארץ ישראל והוא בחלק של בני יהודה שנטלו בדרומה של ארץ ישראל וכן לעתיד לבא בבניו שנאמר (שופטים א ב) יהודה יעלה בתחלה
@10 **ויהי רעב בארץ** . הנה אברהם ירד למצרים מפני הרעב לגור שם להחיות נפשו בימי הבצורת והמצרים עשקו אותו חנם לקחת את אשתו והקב"ה נקם נקמתם בנגעים גדולים והוציאו משם במקנה בכסף ובזהב וגם צוה עליו פרעה אנשים לשלחם ורמז אליו כי בניו ירדו מצרים מפני הרעב לגור שם בארץ והמצרים ירעו להם ויקחו מהם הנשים כאשר אמר (שמות א כב) וכל הבת תחיון והקב"ה ינקום נקמתם בנגעים גדולים עד שיוציאם בכסף וזהב וצאן ובקר מקנה כבד מאד והחזיקו בהם לשלחם מן הארץ לא נפל דבר מכל מאורע האב שלא יהיה בבנים והענין הזה פרשוהו בבראשית רבה (ח ו) רבי פנחס בשם רבי אושעיא אמר אמר הקב"ה לאברהם צא וכבוש את הדרך לפני בניך ואתה מוצא כל מה שכתוב באברהם כתוב בבניו באברהם כתוב ויהי רעב בארץ בישראל כתיב (להלן מה ו) כי זה שנתים הרעב בקרב הארץ ודע כי אברהם אבינו חטא חטא גדול בשגגה שהביא אשתו הצדקת במכשול עון מפני פחדו פן יהרגוהו והיה לו לבטוח בשם שיציל אותו ואת אשתו ואת כל אשר לו כי יש באלהים כח לעזור ולהציל גם יציאתו מן הארץ שנצטווה עליה בתחילה מפני הרעב עון אשר חטא כי האלהים ברעב יפדנו ממות ועל המעשה הזה נגזר על זרעו הגלות בארץ מצרים ביד פרעה במקום המשפט שמה הרשע והחטא
@11 **הנה נא ידעתי וגו' אמרי נא אחותי את** . לא ידעתי למה פחד ממנה עתה יותר מקודם לכן ואם נאמר שהיו המצרים שחורים ומכוערים כדברי רש"י הנה גם לאבימלך מלך פלשתים אמר כן גם הוא גם יצחק שהיה דר בארץ ההיא במצות ה' אולי היו הכנענים בדור ההוא שטופים בעבודה זרה וגדורים מן העריות יותר מאנשי מצרים והפלשתים ואיננו נכון ויתכן כי לא היה להם פחד רק בבואם בעיר מושב המלכים כי היה דרכם להביא למלך האשה היפה מאד ולהרוג את בעלה בעלילה שישימו עליו והנכון בעיני כי זה דרכם למו מעת צאתם מחרן בכל מקום היה אומר "אחותי היא" כי כן אמר (להלן כ יג) ויהי כאשר התעו אותי אלהים מבית אבי אבל הכתוב יזכיר זה במקומות אשר יתחדש להם ענין בדבר והנה זרז אותה עתה כאשר צוה לה מתחילה ויצחק לא פחד בארצו ובעירו רק בבואו אל ארץ פלשתים אחז דרך אביו ואמר למען יטב לי בעבורך וחיתה נפשי בגללך כל ימי היותנו גרים בארץ הזאת עד עבור הרעב כי אברהם מפני הרעב בא לגור בארץ וכעבור הרעב ישוב לארץ אשר נצטוה עליה ונתנה השם לו ולזרעו והיה חושב שיחיו נפשם ברעב ויבא להם ריוח והצלה מאת האלהים לשוב או שיתכן להם לברוח לארץ כנען בהתיאשם ממנה וכתב רש"י הנה נא ידעתי מדרש אגדה עד עכשיו לא הכיר בה מתוך צניעותה ועכשיו על ידי מעשה דבר אחר שעל ידי הדרך אדם מתבזה וזו עמדה ביופיה ולפי פשוטו הנה נא הגיע השעה שיש לדאוג על יופייך וידעתי זה כמה ימים כי יפת מראה את ועכשיו אנו באים בין בני אדם שחורים אחיהם של כושים ולא הורגלו באשה יפה ודומה לו הנה נא אדני סורו נא כל זה לשון הרב והמדרש קבלה בענוה שבהם ונסמך למקרא אבל אין צורך לכל הדברים האלה שאין מלת "נא" מורה על דבר שיתחדש בעת ההיא בלבד אבל על כל דבר הווה ועומד יאמרו כן כי הוא רומז על הענין לומר שהוא עתה ככה הנה נא ידעתי כי אשה יפת מראה את מאז ועד עתה וכן הנה נא עצרני ה' מלדת (להלן טז ב) מנעורי ועד היום הזה וכן הנה נא לי שתי בנות (להלן יט ח) כי לא נולדו עתה וכולם ככה ויראה מפשט הכתובים כי שרה לא קבלה עליה לאמר כן אבל המצרים היו רעים וחטאים מאד וכאשר ראו אותה ויהללו אותה אל פרעה לוקחה אל ביתו ולא שאלו בהם כלל אם אשתו היא או אם אחותו היא והיא שתקה ולא הגידה כי אשתו ואברהם ספר מעצמו כי אחותו היא ולכך הטיבו לו בעבורה וזהו שאמר הכתוב מה זאת עשית לי למה לא הגדת לי כי אשתך היא (להלן פסוק יח) האשים אותו כי בראותו שיקחו אותה היה לו להגיד לפרעה כי אשתו היא וחזר והאשים אותו על אמרו אחרי כן לשרים ולבית פרעה כי אחותו היא ולא האשים את האשה כלל כי אין ראוי שתכחיש היא את בעלה והראוי לה שתשתוק
@12 ראו רמב"ן על בראשית יב יא
@13 ראו רמב"ן על בראשית יב יא
@15 **וטעם ויראו אותה שרי פרעה** . כי כאשר ראו אותה המצרים אמרו ראויה זאת לשרים הגדולים והנה הביאוה אליהם וגם הם יראו לנפשם מנגוע בה כי מפני היופי הגדול ידעו כי המלך יחפוץ בה מאד ויהללו אותה ביניהם לומר ראויה היא למלך לשון רש"י וזה דעת אונקלוס שאמר ושבחו יתה לות פרעה או שהללוה אל המלך עצמו ושלח ולקחה
@17 **וטעם על דבר שרי אשת אברם** . כי בעבור החמס שעשה לשרה גם לאברהם ובזכות שניהם באו עליו הנגעים הגדולים ההם
@18 **ויקרא פרעה לאברם** . יתכן כי בבוא הנגעים פתאום עליו ועל ביתו בעת אשר לוקחה שרה אל ביתו הרהר בדעתו לאמר מה זאת עשה אלהים לנו ושאל אותה והגידה כי היא אשתו ולכן קרא לאברהם והאשים אותואו כאשר אמרו רבותינו (ב"ר מא ב) שלקה בראתן שהמשגל קשה לו וחשש כי שמא אשתו היא ואמר לו בספק מה זאת עשית לי להוציא מפיו האמת כי אם היתה אחותו היה אומר אמנם אחותי היא ואמר ועתה הנה אשתך קח ולך לראות מה ידבר ומה ישיב על תוכחתו ואברהם שתק ממנו ולא השיב אותו דבר מרוב פחדו אז הבין פרעה כי היא אשתו כאשר חשב וצוה עליו פרעה אנשים לשלחם
@19 **וטעם ואקח אותה לי לאשה** . שהיה רצונו שתהיה זאת אשתו המולכת לא תהיה פלגש לו והזכיר זה בעבור שיודה לו אם היא אחותו כאשר פירשתי
@21 **וטעם הוא ואשתו וכל אשר לו** . להודיע שלא גזלו ממנו דבר מכל המתנות הגדולות שנתנו לו בעבור שרה שתהיה למלך ולא אמרו רמיתנו ומתנה בטעות היא וזה מעשה נס
@27 **ויהי ריב** . כתב רש"י לפי שהיו רועיו של לוט מרעין בהמתם בשדות אחרים והיו רועיו של אברם מוכיחין אותם על הגזל והם אומרים נתנה הארץ לאברם ולו אין יורש ולוט יורשו ואין זה גזל והכתוב אמר והכנעני והפריזי אז יושב בארץ ולא זכה בה עדיין אברם ומדרש רבותינו הוא (ב"ר מא ה) ואני תמה כי המתנה שנאמרה לאברם לזרעו היתה שנאמר למעלה (יב ז) לזרעך אתן את הארץ הזאת והיאך יירשנו לוט אולי שמעו הרועים המתנה וטעו והכתוב אומר כי גם ללוט גם לאברם איננה עתה ולפי זה מה שאמר תחילה כי היה רכושם רב לאמר כי מפני הרכוש הרב לא ישא אותם הארץ והוצרכו רועי לוט להכניס מקניהם בשדות שיש להם בעלים וזאת סבת המריבה ועל דרך הפשט היתה המריבה על המרעה כי לא נשא אותם הארץ וכאשר היה מקנה אברם רועה באחו היו רועי לוט באים בגבולם ורועים שם והנה אברם ולוט היו גרים ותושבים בארץ ופחד אברם פן ישמע הכנעני והפריזי יושב הארץ כובד מקניהם ויגרשום או יכו אותם לפי חרב ויקחו להם מקניהם ורכושם כי ישיבת הארץ עתה להם לא לאברם וזה טעם והכנעני והפריזי כי הזכיר שהיו עמים רבים יושבים בארץ ההיא ולהם ולמקניהם אין מספר ולא ישא אותם הארץ ואת אברם ולוט וממלת אז יראה לי כי העמים היו בארץ בימים ההם יושבי אהל ומקנה נאספים מקצתם אל עיר אחת ורועים שם שנה או שנתים ונוסעים משם אל גבול אחר אשר לא רעו אותו וכן יעשו תמיד כמנהג בני קדר והכנעני והפריזי היו אז בארץ הנגב ובשנה האחרת יבואו שם היבוסי והאמורי
@30 **כגן ה' כארץ מצרים** . יאמר כי ארץ הככר כולה משקים אותה ברגל מן הירדן כדרך הנעשה בגן ה' שנאמר בו (לעיל ב י) ונהר יוצא מעדן להשקות את הגן וכדרך שהיא בארץ מצרים שנאמר בה (דברים יא י) והשקית ברגלך כגן הירק והזכיר שני המקומות אמר "כגן ה'" שהמקום הטוב בתחתונים כן הוא כולו משקה והזכיר "כארץ מצרים" מקום ידוע לרעיה ורבותינו אמרו (ספרי עקב לח) כגן ה' לאילנות כארץ מצרים לזרעים ירצו לפרש שיש בככר נהרות גדולים ישקו אילני הגנות כגן ה' ובו יאורים כארץ מצרים ישקו גן הירק ובחר לו לוט בזה כי הארץ שישקו אותה כן רחוקה מן הבצורת וטובה למרעה
@32 **וטעם אברם ישב בארץ כנען** . בשאר ארץ כנען כולה שלא יעמוד במקום אחד אבל בכל ארץ כנען יגור ולוט נתישב במקום אחד ממנה בערי הככר כי ערי הככר מכלל ארץ כנען וטעם בערי הככר פעם בזו ופעם בזו מפני כובד המקנה וזה טעם ויבחר לו לוט את כל ככר הירדן כי התנה עם אברם שלא יבא בכל הככר
@33 **וטעם ואנשי סדום רעים וחטאים** . יאשים הכתוב את לוט שלא נמנע מלשכון עמהם כדברי רש"י וידבר עוד בזכות הצדיק שלא נפל חבלו במקום אשר שמה הרשע כי לא ינוח שבט הרשע על גורל הצדיקים וכל ערי הככר רעים וחטאים לה' מאד כי על כן נהפכו אף על פי שכל בני כנען אנשי תועבות גדולות כי כן כתוב (ויקרא יח כז)
@37 **קום התהלך בארץ לארכה ולרחבה** . יתכן שזה רשות כרצונו אמר לו בכל אשר תרצה ללכת בארץ לך כי אהיה עמך ושמרתיך מרעת הגוים כי לך אתננה כלומר שלך תהיה ואם היא מצוה שילך בה כל ארכה ורחבה להחזיק במתנתו כאשר פירשתי (לעיל יב ו) לא נצטווה לעשות זה מיד והנה עשה כן כי עתה היה במזרח ואחר כן הלך אל ארץ פלשתים שהוא במערב והנה קיים המצוה בחייו וטעם לך ולזרעך שתחזיק במתנה מעכשיו להנחילה לזרעך כמו שאמרו רבותינו (ב"ב קיט) ירושה היא להם מאבותיהם ועל דרך הפשט יתכן שיהיה מושל עליה ונשיא אלהים בתוכה בכל מקום שילך בארץ ההיא
@39 **ויהי בימי אמרפל מלך שנער** . המעשה הזה אירע לאברהם להורות כי ארבע מלכיות תעמודנה למשול בעולם ובסוף יתגברו בניו עליהם ויפלו כלם בידם וישיבו כל שבותם ורכושם והיה הראשון מהם מלך בבל כי כן העתיד כדכתיב (דניאל ב לח) אנת הוא רישא די דהבא ואולי "אלסר" שם עיר במדי או בפרס ו "עילם" בעיר ההיא המלך מלך יון הוא המלך הראשון ומשם נתפשט מלכותו כשנצח דריוש וכבר הזכירו זה רבותינו (ע"ז י) רבי יוסי אומר שש שנים מלכו בעילם ואחר כך נתפשטה מלכותם בכל העולם כולו ו"מלך גוים" המלך על עמים שונים אשר שמוהו עליהם לראש ולקצין רמז למלך רומי אשר המלך על עיר מקובצת מעמים רבים כיתים ואדום ויתר גוים וכך אמרו בבראשית רבה (מב ב) אמר רבי אבין כשם שפתח בארבע מלכיות כך אינו חותם אלא בארבע מלכיות וכו' ושם עוד (מב ד בשינוי לשון) ויהי בימי אמרפל מלך שנער זו בבל אריוך מלך אלסר זו מדי כדרלעומר מלך עילם זו יון ותדעל מלך גוים זו מלכות אדום שהיא מכתבת טירוניא מכל אומות העולם
@40 **וטעם ומלך בלע** . מפני שמלך על עיר קטנה ואנשים בה מעט ולא שם לו על פני חוץ
@44 **איל פארן** . כתרגומו מישר פארן ואני אומר שאין איל לשון מישור אלא מישור של פארן איל שמו ושל ממרא אלוני שמו ושל ירדן ככר שמו ושל שטים אבל שמו וכולם מתורגמין מישרא וכל אחד שמו עליו לשון רש"י ואלו היה כן היה אונקלוס מתרגם בשמם "אילא דפארן" "אלוני דממרא" כמנהגו בשמות ומי הגיד לו במקומות הרבים ההם המישור הם כולם או הרים הגבוהים ו"ממרא" שם האיש האמורי אחי אשכול ואחי ענר בעלי ברית אברם והמקום ההוא שלו כמו שאמר (להלן פסוק יג) אלוני ממרא האמורי כאשר פרשתי (לעיל יב ו) אבל "איל פארן" מקום אילים כי יבשו מאילים אשר חמדתם (ישעיהו א כט) ו"אלוני" מקום אלונים כאלה וכאלון (שם ו יג) אלונים מבשן (יחזקאל כז ו) והנהוג בהם להיותם נטועים במישור לפני המדינות להיות לעיר כמו מגרש וכן תרגום "אלון בכות" (להלן לה ח) "מישור בכותא" ושם איננו שם העצם למקום רק הוא שם לאלון הנטוע שם כמו שמפורש (שם) תחת האלון אלא שהוא רודף הענין לא המלות והתרגום הירושלמי אמר ב"איל פארן" ו"אלוני ממרא" "מישרא" כדברי אונקלוס ואמר ב"אלון בכות" "בלוט בכותא" כי "אלון בכות" אצלו שם לאילן לא למקום ואונקלוס סבר שהוא שם למקום כי היו בו אלונים רבים כמו "אלוני ממרא" ולכך אמר "האלון" והנה כולם שמות תאר אבל "ככר הירדן" לשון מישור ממש הוא כי כן יקרא בלשון הקודש המקום שהנהרות מתפשטין בהם במרוצת המים הנגרים השוטפים שם ולכן אמר (להלן יט יז) ואל תעמוד בכל הככר ההרה המלט וכן כר נרחב (ישעיהו ל כג) לבשו כרים הצאן ועמקים יעטפו בר (תהלים סה יד) פעמים יכפלו המלה ופעמים יסירו הכפל כמו בת עין (שם יז ח) וזולתם רבים ויקראו גם כן השלוחים המהירים בשם הזה לכרי ולרצים (מלכים ב יא ד) שרי המאות ואת הכרי (שם יט) וכן בכרכרות (ישעיהו סו כ) שם לגמלים המריצין שהזכירום בתלמוד (מכות ה) "גמלא פרחא" וממנו "מכרכר" כפולים ואבל השטים (במדבר לג מט) וכן "אבל מחולה" (שופטים ז כב) תרגמו אותו "מישר" הוא המקום הנחרב אין בו נטע ולא בנין כי הלשון אצלם לשון חרבה ושממה כמו ויאבל חיל וחומה (איכה ב ח) אבל תירוש אומללה גפן (ישעיהו כד ז)
@45 **אל עין משפט** . על שם העתיד שעתידים משה ואהרן להשפט שם על עסקי אותו העין לשון רש"י מדברי אגדה (במד"ר יט יד) ולא הבינותי זה כי "קדש" זה הוא "קדש ברנע" כי הוא ב"איל פארן אשר על המדבר" וממנו נשתלחו מרגלים בשנה שניה שנאמר (במדבר יג כו) אל מדבר פארן קדשה וכתוב (דברים א יט כב) ונבא עד קדש ברנע ותאמרו נשלחה אנשים לפנינו ושם ישבו ישראל ימים רבים אבל "קדש" ששם משפט הצדיקים הוא במדבר צין שבאו שם בשנת הארבעים שנאמר (במדבר כ א) ויבאו בני ישראל כל העדה מדבר צין בחדש הראשון וישב העם בקדש וגמר הפרשה אולי המדרש על השם בלבד הוא רמז הכתוב כי השם הזה "קדש" הוא יהיה עין משפט ואונקלוס אמר "מישר פילוג דינא" ולא ידעתי מהו אולי הוא מלשון פלגים יבלי מים (ישעיהו ל כה) מי פלג לשטף תעלה (איוב לח כה) וכן בלשון חכמים (אסתר רבה ה) "פלגו של ים" יאמר כי במישור ההוא מעין המשפט ועומק הדין כי היה מישור נאה מעותד למלכים שם ישבו לשפוט את כל הגוים בארצות ההם
@45 "שדה העמלקי" - לשון רש"י עדיין לא נולד עמלק ונקרא על שם העתיד ולא ידעתי אם רצונו לומר כי משה רבינו קרא המקום בשם שהוא נקרא בימיו ואם כן אין בכאן דבר עתיד או מה העתיד הזאת שיתנבאו הגוים לקרוא המקום כן ולשון בראשית רבה (מב ז) עדיין לא נולד עמלק ואת אמרת את כל שדה העמלקי אלא מגיד מראשית אחרית וזה דרך הדרש להם במקומות רבים גם בנהרות גן עדן אמרו (ב"ר טז ב) כלשון הזה וכוונתם לומר כי מעת צאת הנהרות נאמר כי הנהר הולך קדמת ארץ העתידה להיות לאשור והנכון בעיני בשדה העמלקי כי היה בימים הקדמונים אדם נכבד מבני החורי יושב הארץ ומשל על המקום ההוא ושמו עמלק ואליפז בכור עשו קרא שם בנו על שם האיש ההוא ואולי ממשפחת תמנע אמו היה ומשל גם במקום ההוא והיה שם אלוף עליהם
@48 **בארת בארת חמר** . בארות הרבה היו שם שנוטלין משם אדמה לטיט הבנין ומדרש אגדה שהיה הטיט מוגבל בהן ונעשה נס למלך סדום שיצא משם לפי שהיו באומות מקצתן שלא היו מאמינים באברם שנצל מכבשן האש וכיון שיצא זה מן החמר האמינו באברם למפרע לשון רש"י ואין ספק כי פירוש בארות חמר בארות אשר בהם רפש וטיט כענין שכתוב (ירמיהו לח ו) ובבור אין מים כי אם טיט ויטבע ירמיהו בטיט וכתוב (תהלים מ ג) ויעלני מבור שאון מטיט היון ויתכן שיצא משם כראוי בלא נס ואני תמה במדרש ההגדה הזה כי האומות שלא היו מאמינים שעשה הקב"ה נס לאברהם בראותם נסו של מלך סדום לא יוסיפו אמונה בהקב"ה כי מלך סדום עובד עבודה זרה היה והנה נסו או יחזק ידי עובדי עבודה זרה או שיאמינו בכל הנסים שיהיו בכשפים או מקרה באפשרות רחוקה ונסו יתן ספק בלב המאמינים בנסו של אברהם ואולי יפרשו ויצא מלך סדום לקראתו שיצא מן הבור כשעבר אברהם עליו כי נעשה לו נס לכבוד אברהם שיצא לקראתו לכבודו ולברכו ואפשר כי אברהם בשובו הביט בבור ההוא כי חפץ להציל המלכים ולהשיב להם רכושם והנה נעשה הנס על ידו ואם נעשה למלך סדום נס לכבוד אברהם כל שכן שיש להאמין שיעשה נס לאברהם להציל ממות נפשו ונאמר כי מלך עמורה כבר מת כאשר עבר אברהם עליו או שנפל בבור אחר כי שמה רמז לעמק
@53 **ויחלק עליהם לילה** . כתב רש"י לפי פשוטו כדרך הרודפים שמתפלגים אחר בורחיהם כשבורחין זה לכאן וזה לכאן לילה כלומר לאחר שחשכה לא נמנע מלרדפם והנכון כי רדף אותם ביום עד דן עם כל מחנהו וכאשר חשך עליהם הלילה ולא היה רואה אי זה דרך אשר יברחו בה חלק עמו ועבדיו לשנים או שלשה ראשים ולקח החלק האחד עמו ורדפו אחריהם בכל הדרכים והכום עד חובה אשר משמאל לדמשק וחזר מלרדוף אחריהם ושיעורו ויחלק עליהם הוא ועבדיו לילה
@53 "וירדפם עד חובה אשר משמאל לדמשק" - ידוע כי מרחק רב מן אלוני ממרא אשר בחברון בארץ יהודה לדמשק אשר הוא חוצה לארץ אם כן רדף אחריהם ימים רבים עד הוציאו אותם מן הארץ כי הם אל בבל ארצם היו חוזרים או שהיה נס גדול כאשר דרשו רבותינו (ב"ר מג ג) בארח ברגליו לא יבא (ישעיהו מא ג)
@56 **ומלכי צדק מלך שלם** . היא ירושלים כענין שנאמר (תהלים עו ג) ויהי בשלם סוכו ומלכה יקרא גם בימי יהושע "אדני צדק" (יהושע י א) כי מאז ידעו הגוים כי המקום ההוא מבחר המקומות באמצע הישוב או שידעו מעלתו בקבלה שהוא מכוון כנגד בית המקדש של מעלה ששם שכינתו של הקב"ה שנקרא "צדק" ובבראשית רבה (מג ו) המקום הזה מצדיק את יושביו ומלכי צדק אדוני צדק נקראת ירושלם צדק שנאמר (ישעיהו א כא) צדק ילין בה והזכיר והוא כהן לאל עליון להודיע כי אברהם לא היה נותן מעשר לכהן לאלהים אחרים אבל מפני שידע בו שהוא כהן לאל עליון נתן לו המעשר לכבוד השם והרמז לאברהם מזה כי שם יהיה בית אלהים ושם יוציא זרעו המעשר והתרומה ושם יברכו את ה' ועל דעת רבותינו (נדרים לב) שאומרים כי מלכי צדק הוא שם בן נח הלך מארצו לירושלם לעבוד שם את ה' והיה להם לכהן לאל עליון כי הוא אחי אביהם הנכבד כי ירושלים מגבול הכנעני היא מעולם ורש"י כתב למעלה (יב ו) והכנעני אז בארץ היה הולך וכובש את ארץ ישראל מזרעו של שם זקנו של אברהם שבחלקו של שם נפלה כשחלק נח לבניו את הארץ (ספרא קכו) שנאמר ומלכי צדק מלך שלם ואין זה נכון כי "גבול הכנעני מצידון" (לעיל י יט) יכלול כל ארץ ישראל וגבול בני שם במזרח ממשא רחוק מארץ ישראל אבל אם חלק נח לבניו הארצות ונתן לשם ארץ ישראל היה זה כ"מחלק נכסיו על פיו" וישבו בה בני כנען עד אשר ינחיל אותה השם לזרע אוהבו כאשר הזכרתי כבר (לעיל י טו)
@56 "והוא כהן לאל עליון" - בעבור היות בכל העמים כהנים משרתים למלאכים הנקראים "אלים" כענין שנאמר (שמות טו יא) מי כמוכה באלים יקרא הקב"ה "אל עליון" וענינו התקיף הגבוה על כל גבוהים כמו יש לאל ידי (להלן לא כט) ומלכי צדק לא הזכיר השם אבל אברהם אמר ה' אל עליון (להלן פסוק כב)
@57 **קונה שמים וארץ** . כתב רש"י קונה כמו עושה על ידי עשייתו קנאן להיות לו ואלה שני פנים הם ואולי כן הדבר שיבא לשון קנין בענין העשייה וכן כי אתה קנית כליותי (תהלים קלט יג) שיכפול תסוכני בבטן אמי וכן הלא הוא אביך קנך הוא עשך ויכוננך (דברים לב ו) כי הלשון יאמר "קנין" בעשייה וההפך אשר עשו בחרן (לעיל יב ה) קנו ומאשר לאבינו עשה (להלן לא א) והנכון מה שאמר עוד קנאן להיות לו כי כל אשר לאדם יקרא קנינו ויקראו הצאן "מקנה" בעבור היותו עיקר רכוש האדם ולשון חכמים (ב"מ י) המגביה מציאה לחבירו קנה חבירו הבטה בהפקר קניא (שם קיח) חצרו של אדם קונה לו שלא מדעתו (שם יא) וכן בכל מקום תבוא להם במקום זכיה כלומר שהוא שלו ולזה נתכוין אונקלוס שתרגם דקניניה ולא אמר "קנה"
@58 **ויתן לו מעשר מכל** . אברהם לא רצה לקחת לעצמו מחוט ועד שרוך נעל אבל חלק הגבוה הפריש לתתו לכהן ומלך סדום יצא לקראת אברהם אל עמק שוה לכבדו והלך עמו עד שלם שהוציא מלכי צדק לחם ויין לעם אשר ברגליו ולא בקש מלך סדום ממנו דבר אבל כאשר ראה נדיבת לבו וצדקתו שנתן המעשר אז בקש גם הוא הנפש בדרך צדקה ואברהם בטח באלהיו שיתן לו עושר ונכסים וכבוד ולא רצה לקחת ממנו דבר והשיב לו כל רכוש סדום שהוא שלו וכל רכוש עמורה להשיב אותו לבעליו כי בכל בקש ממנו הנפש ובכל היתה טענתו שלא יאמרו הם העשירו את אברם ושאר המקומות הנזכרים לפי חרב הכו אותם ולא לקחו מערי המלכים רק רכוש סדום ועמורה כי בעבור שאבדו מלכיהם נשארו עזובות עריהם ויתכן שיהיה זה מה שאמר "אם מחוט ועד שרוך" ישאר בידי מכל הרכוש הבא אלי מכולכם "ואם אקח מכל אשר לך" ברכושך שנתת אתה לי
@60 **וטעם הרימותי ידי אל ה'** . לשון שבועה מרים אני ידי לאל עליון וכן בי נשבעתי (להלן כב טז) נשבע אני לשון רש"י וכן מצאתי בספרי (ואתחנן לג) מצינו בכל הצדיקים שמשביעין את יצרן שלא לעשות באברהם הוא אומר הרימותי ידי אל ה' והנה הוא כלשון וירם ימינו ושמאלו אל השמים וישבע בחי העולם (דניאל יב ז) ואונקלוס אמר ארימית ידי בצלו קדם ה' יאמר התפללתי אל ה' וכפי פרושות השמים אם אקח מכל אשר לך כלומר כה יעשה לי אלהים וכה יוסיף אם אקח והנכון בעיני כי אמר הרימותי ידי אל ה' להיות הקדש וחרם לפניו אם אקח מכל אשר לך כי ההקדשות יקראו כן "תרומת יד" כלשון כל מרים תרומת כסף ונחשת (שמות לה כד) וכל איש אשר הניף תנופת זהב לה' (שם כב) ואמר כן בעבור שנתן ממנו מעשר כי כל אשר יקח מכל אשר לו יהיה תרומה לה' לא יהנה ממנו דבר ובבראשית רבה (מג ט) עשאן תרומה כמה דאת אמר (במדבר יח כו) והרמותם ממנו תרומת ה'
@63 **היה דבר ה' אל אברם במחזה** . זכה עתה אברהם להיות לו דבר ה' במחזה ביום כי מתחילה היתה נבואתו במראות הלילה וטעם היה דבר ה' אל אברם במחזה כטעם וכל העם רואים את הקולות (שמות כ יח) וסודם ליודעי חן
@63 "אל תירא אברם" - היה מתירא משני דברים מן המלכים פן ירבו צבאותם עליו הם או העומדים תחתם ובמלחמה ירד ונספה או יומו יבא למות בלא זרע והבטיחו כי הוא יהיה מגן בעדו מהם ועוד יהיה שכר לכתו עם ה' הרבה מאד
@64 **ויאמר אברם ה' אלהים מה תתן לי** . הנה הצלתני מן המלכים אבל מן הכרת לא הבטחת אותי רק אמרת שתרבה לי שכר הרבה ומה יהיה שכרי בלא בנים והנה לא עלה בדעתו שיהיה השכר הגדול הזה עולם הבא כי זה אין צורך להבטחה כי כל עובד אלהים ימצא חיים לפניו אך בעולם הזה יש צדיקים שמגיע עליהם כמעשה הרשעים על כן צריכים בטחון ועוד כי הרבה מאד לאמר שיזכה לשתי שולחנות בכל הטוב הראוי לצדיקים הגמורים מאין עונש כלל ועוד כי ההבטחה למה שהיה מתירא ממנו וחזר ופירש לו הבטחתו שלא יפחד גם מזה כי ישים זרעו ככוכבי השמים לרוב ויש עליך לשאול שכבר נאמר לו לאברהם (לעיל יג טו) כי את כל הארץ אשר אתה רואה לך אתננה ולזרעך עד עולם ושמתי את זרעך כעפר הארץ ואיך יאמר עתה ואנכי הולך ערירי והנה בן ביתי יורש אותי ולמה לא האמין בנבואה הראשונה כאשר יאמין בזאת והתשובה כי הצדיקים לא יאמינו בעצמם בחטאם בשגגה וכתוב (ירמיהו יח ט) רגע אדבר על גוי ועל ממלכה לבנות ולנטוע ושב הגוי ההוא ועשה הרע לפני ונחמתי על הטובה והנה ראה עצמו בא בימים ולא נתקיימה נבואתו וחשב כי חטאיו מנעו הטוב ואולי חשש עתה פן יענש על הנפשות שהרג כדברי רבותינו (ב"ר מד ה) וכלשון הזה אמרו בבראשית רבה (עו ב) ויירא יעקב מאד ויצר לו (להלן לב ח) מכאן שאין הבטחה לצדיקים בעולם הזה וכו'
@64 "מה תתן לי ואנכי הולך ערירי" - פירשו בו (יב"ע) אני מת בלא בנים כטעם כי הולך האדם אל בית עולמו (קהלת יב ה) והנכון בעיני כי מתחלה יתאונן מה יהיה שכרי אחרי שאין לי בנים ואנכי הולך נע ונד בארץ נכריה יחידי כערער בערבה אין יוצא ואין בא בביתי זולתי אליעזר איש נכרי אשר לקחתי לי מדמשק לא מבית אבי ולא מארצי ואחר כך אמר הן לי לא נתתה זרע כאשר הבטחתני והנה בן ביתי הנזכר יורש אותי כי זקנתי ויבא עתי בלא זרע והנה אני ענוש ואבד שכרי אשר הבטחתני בו בראשונה
@66 **והנה דבר ה' אליו לאמר לא יירשך זה** . בעבור היות לו הבן היורש אחרי זקנתו לא הבטיחו רק על הירושה שלא ידאג כי זרעו יירשנו וטעם והנה דבר ה' אליו כי עוד בפיו והנה בן ביתי יורש אותי ובא אליו פתאום דבר השם לאמר לא יירשך זה
@67 **ויוצא אותו החוצה** . לפי פשוטו הוציאו מאהלו אל החוץ לראות הכוכבים ולפי מדרשו אמר לו צא מאצטגנינות שלך שראית במזלות שאינך עתיד להעמיד בן אברם אין לו בן אברהם יש לו בן שרי לא תלד שרה תלד לשון רש"י והנה אברם הוליד את ישמעאל אבל פירוש המדרש כי אברם מבקש בן יורש אותו כמו שאמר
@67 "והנה בן ביתי יורש אותי" - והקדוש ברוך הוא אמר לו לא יירשך זה כי אם אשר יצא ממעיך הוא יירשך וצא מן האצטגנינות שלך אברם אינו מוליד בן ליורשו אבל אברהם מוליד בן ליורשו ויתכן שהיה האצטגנינות על זיווגם שאברם ושרי לא יולידו זה מזה ואברהם ושרה יולידו אבל לפי דעתי שרה תוספת במדרש לומר שהיה כן גם בשרה אבל הקדוש ברוך הוא לא הבטיחו עתה בשרה וגם בעת נבואת המילה עדיין היה אברהם מסתפק בשרה שתלד
@68 **והאמן בה' ויחשבה לו צדקה** . פירש רש"י הקדוש ברוך הוא חשב לו צדקה וזכות על האמונה שהאמין בו ואיני מבין מה הזכות הזאת למה לא יאמין באלהי אמן והוא הנביא בעצמו ולא איש אל ויכזב ומי שהאמין לשחוט את בנו היחיד האהוב ושאר הנסיונות איך לא יאמין בבשורה טובה והנכון בעיני כי יאמר שהאמין בה' וחשב כי בצדקו של הקב"ה יתן לו זרע על כל פנים לא בצדקת אברם ובשכרו אף על פי שאמר לו "שכרך הרבה מאד" ומעתה לא יירא פן יגרום החטא ואף על פי שבנבואה הראשונה חשב שתהיה על תנאי כפי שכר מעשיו עתה כיון שהבטיחו שלא יירא מן החטא ויתן לו זרע האמין כי נכון הדבר מעם האלהים אמת לא ישוב ממנה כי צדקת ה' היא ואין לה הפסק כענין שכתוב (ישעיהו מה כג) בי נשבעתי נאם ה' יצא מפי צדקה דבר ולא ישוב או יאמר כי אברהם האמין שיהיה לו זרע יורש על כל פנים והקב"ה עוד חשב לו ההבטחה הזו שהבטיחו צדקה כי בצדקת ה' יעשה כן כמו אלהים חשבה לטובה (להלן נ כ) וכן ותחשב לו לצדקה (תהלים קו לא) דפנחס שחשב לו הבטחתו זו שבטח בשם במעשה ההוא לצדקה לדור ודור כי לעולם ישמור לו האל בעבורה צדקתו וחסדו כדרך לעולם אשמור לו חסדי (שם פט כט)
@69 **אני ה' אשר הוצאתיך מאור כשדים לתת לך את הארץ הזאת לרשתה** . כבר פירשתי זה (לעיל יא כח) כי יאמר מעת שהוצאתיך מאור כשדים ועשיתי לך נס היה הרצון לפני לתת לך הארץ הזאת והנה עתה לא גזר שיתננה לו אבל אמר שהוציאו מאור כשדים על דעת שיתננו לו ולכן חשש אברהם פן יהיה בירושת הארץ תנאי המעשים אף על פי שאמר לו פעמים (לעיל יב ז יג טו) לזרעך אתן את הארץ הזאת כי עתה לא יגזור המתנה כאשר גזר לו זרע ולכן אמר במה אדע כי אירשנה ואינו כשאלת "מה אות" (מלכים ב כ ח) וגם הקדוש ברוך הוא לא עשה עמו כשאר האותות להראות לו אות או מופת בדבר נפלא אבל בקש אברהם שידע ידיעה אמיתית שיירשנה ולא יגרום חטאו או חטא זרעו למנעה מהם או שמא יעשו הכנענים תשובה ויקיים בהם רגע אדבר על גוי ועל ממלכה לנתוש ולנתוץ להאביד ושב הגוי ההוא מרעתו ונחמתי על הרעה (ירמיהו יח ז) והקדוש ברוך הוא כרת עמו ברית שיירשנה על כל פנים
@71 **עגלה משולשת ועז משולשת** . פירש רבי אברהם בת שלש שנים אבל אונקלוס אמר שלש וכן הדבר כי בת שלש לא תקרא עגלה כמו ששנינו (פרה א א) וחכמים אומרים עגלה בת שתים פרה בת שלש ורמז כי שלשה קרבנות מהן יקריבו לפניו זרעו העולה והחטאת והשלמים כי האשם כחטאת הוא אין ביניהם לבד השם ויתכן שיהיה טעם "משולשת" שיביא אותן רצופות ויהיה כל מין לבד וכן כי משולשות הנה (יחזקאל מב ו) שהיו הלשכות העליונות והתיכונות והתחתונות
@72 **ויבתר אותם בתוך** . לכרות עמו ברית לעבור בין הבתרים האלה ונרמז לו גם כן כי מאלה יהיה כל קרבן בבהמה ובעוף כי הגוזל בן יונה ואמר בו גוזל שלא הוכשרו במין ההוא אלא הקטנים ואף על פי שכל קטני העופות יקראו גוזלים שנאמר (דברים לב יא) כנשר יעיר קנו על גוזליו ירחף הבין אברהם מעצמו המין הנבחר או הקריב בן יונה ברצונו והכתוב בחר לעולם במין אשר הקריב הזקן והנה ידע שאלה יהיו הקרבנות וכל הקרבנות יבתרו העולה לנתחים והשלמים לחזה ושוק וחלבים והחטאת והאשם לחלביהן
@72 "ואת הצפור לא בתר" - נתן התור והגוזל איש לקראת רעהו כי גם הם היו בברית אבל לא בתר אותם בתוך כי בכל העוף הקרב נאמר לא יבדיל (ויקרא א יז) ובבראשית רבה (מד יד) הראה לו הקב"ה שמבדילין בעולת העוף ואין מבדילין בחטאת העוף
@73 **וירד העיט על הפגרים** . לאכול אותם כמנהג העופות
@73 "וישב אותם" - נרמז לו כי יבאו העמים לבטל הקרבנות וזרע אברהם יבריחום
@74 **והנה אימה חשכה גדולה נופלת** . דרשו בו רמז לשעבוד ארבע גליות כי מצא הנביא בנפשו אימה ואחר כך בא בחשכה ואחר כך גדלה החשכה ואחר כך הרגיש כאלו היא נופלת עליו כמשא כבד תכבד ממנו אמרו (ב"ר מד יז) אימה זו בבל חשכה זו מדי שהחשיכה עיניהם של ישראל בצום ובתענית גדולה זו מלכות אנטיוכס נופלת עליו זו אדום והיה הענין הזה לאברהם כי כשהקב"ה כרת עמו ברית לתת הארץ לזרעו לאחזת עולם אמר לו כמשייר במתנתו שארבע גליות ישתעבדו בבניו וימשלו בארצם וזה בעל מנת אם יחטאו לפניו ואחרי כן הודיעו בבאור גלות אחרת שיגלו תחלה שהוא גלות מצרים שכבר נענש בו כאשר פירשתי (לעיל יב י)
@75 **כי גר יהיה זרעך** . זה מקרא מסורס ושיעורו כי גר יהיה זרעך בארץ לא להם ארבע מאות שנה ועבדום וענו אותם ולא פירש כמה ימי העבדות והעינוי והרבה מקראות מסורסות יש בכתוב וכן בא אלי העבד העברי אשר הבאת לנו לצחק בי (להלן לט יז) וכן וכל הארץ באו מצרימה לשבור אל יוסף (שם מא נז) וכן כי כל אוכל חמץ ונכרתה הנפש ההיא מישראל מיום הראשון עד יום השביעי (שמות יב טו) וכן ביום ההוא ישליך האדם את אלילי כספו ואת אלילי זהבו אשר עשו לו להשתחות לחפור פירות ולעטלפים (ישעיהו ב כ) וכן לכו שמעו ואספרה כל יראי אלהים אשר עשה לנפשי (תהלים סו טז) וכן לי יזעקו אלהי ידענוך ישראל (הושע ח ב) וכן והיו לי אמר ה' צבאות ליום אשר אני עושה סגלה וחמלתי עליהם (מלאכי ג יז) ורבים כן וענין הכתוב אף על פי שאני אומר לך לזרעך נתתי את הארץ הזאת ידוע תדע כי טרם תתי אותה להם יהיו גרים בארץ לא להם ארבע מאות שנה וגם יעבדום וענו אותם ורבי אברהם אמר ידוע תדע כי גר יהיה זרעך בעבדות וענוי עד קץ ארבע מאות שנה מן היום הזה ואם כן הודיעו קץ הגאולה ולא הודיעו כמה ימי הגלות גם נכון הוא "()" "סגירה"
@76 **וגם את הגוי אשר יעבודו** . וגם לרבות ד' גליות על ששעבדו את ישראל לשון רש"י ועל דרך הפשט יאמר כאשר דנתי את בניך בגלות וענוי על עון גם את הגוי אשר יעבודו אדין על החמס אשר יעשו להם והנכון בעיני כי טעם וגם אף על פי שאני גזרתי על זרעך להיות גרים בארץ לא להם ועבדום וענו אותם אף על פי כן אשפוט את הגוי אשר יעבודו על אשר יעשו להם ולא יפטרו בעבור שעשו גזרתי והטעם כמו שאמר הכתוב (זכריה א יד) וקנאתי לירושלם ולציון קנאה גדולה וקצף גדול אני קוצף על הגוים השאננים אשר אני קצפתי מעט והמה עזרו לרעה ואומר (ישעיהו מז ו) קצפתי על עמי חללתי נחלתי וגו' וכן היה במצרים שהוסיפו להרע כי השליכו בניהם ליאור וימררו את חייהם וחשבו למחות את שמם וזה טעם דן אנכי שאביא אותם במשפט אם עשו כנגזר עליהם או הוסיפו להרע להם וזהו מה שאמר יתרו כי בדבר אשר זדו עליהם (שמות יח יא) כי הזדון הוא שהביא עליהם העונש הגדול שאבדם מן העולם וכן כי ידעת כי הזידו עליהם (נחמיה ט י) והרב נתן טעם בספר המדע (הלכות תשובה ו ה) לפי שלא גזר על איש ידוע וכל אותם המריעים לישראל אלו לא רצה כל אחד מהם הרשות בידו לפי שלא נגזר על איש ידוע ולא נתכנו דבריו אצלי שאפילו גזר שאחד מכל האומות יריע להם בכך וכך וקדם זה ועשה גזרתו של הקב"ה זכה בדבר מצוה ומה טעם בדבריו כאשר יצוה המלך שיעשו בני מדינה פלונית מעשה מן המעשים המתרשל ומטיל הדבר על האחרים חומס וחוטא נפשו והעושה יפיק רצון ממנו וכל שכן שהכתוב אמר וגם את הגוי אשר יעבודו שיעבדו הגוי כולו והם הלכו מעצמם למצרים אבל הטעם כאשר כתבתי וכבר הזכירו רבותינו הענין הזה אמרו בואלה שמות רבה (ל טו) משל לאדון שאמר לבנו "יעשה עם פלוני ולא יצערנו" הלך ועשה אף על פי שעשה עמו חנם לא הניח שלא היה מצערו כשנתרצה האדון לבנו גזר על מצעריו הריגה כך גזר הקב"ה שיהיו ישראל משועבדין במצרים עמדו עליהם ושעבדום בחוזק אמר הקב"ה היה לכם לנהוג בם כעבדים ויעשו צרכיכם אני קצפתי מעט והמה עזרו לרעה (זכריה א טו) עד כאן לשונם ודבר ברור הוא כי השלכת בניהם ליאור אינה בכלל "ועבדום וענו אותם" אבל היא עקירתם לגמרי וכן מה שאמרו תחלה הבה נתחכמה לו פן ירבה (שמות א י) אינו בכלל עבדות וענוי מלבד מה שהוסיפו בענוי עצמו וימררו את חייהם בעבודה קשה וגו' והוא מה שאמר הכתוב (דברים כו ז) וירא את עניינו ואת עמלינו ואת לחצנו ודע והבן כי האיש שנכתב ונחתם בראש השנה להריגה לא ינקה הליסטים ההורג אותו בעבור שעשה מה שנגזר עליו הוא רשע בעונו ימות ודמו מיד הרוצח יבוקש אבל כאשר תצא הגזירה על פי נביא יש בעושה אותה דינים כי אם שמע אותה ורצה לעשות רצון בוראו כנגזר אין עליו חטא אבל יש לו זכות בו כאשר אמר ביהוא (מלכים ב י ל) יען אשר הטיבות לעשות הישר בעיני ככל אשר בלבבי עשית לבית אחאב בנים רבעים ישבו לך על כסא ישראל אבל אם שמע המצוה והרג אותו לשנאה או לשלול אותו יש עליו העונש כי הוא לחטא נתכוון ועבירה הוא לו וכן הכתוב אומר בסנחריב (ישעיהו י ה) הוי אשור שבט אפי וגו' בגוי חנף אשלחנו ועל עם עברתי אצונו ואמר הכתוב והוא לא כן ידמה ולבבו לא כן יחשוב כי להשמיד בלבבו ועל כן הענישו בסוף כמו שנאמר (שם י יב) והיה כי יבצע ה' את כל מעשהו אפקוד על פרי גודל לבב מלך אשור ועל תפארת רום עיניו וגו' ואמר בו שה פזורה ישראל אריות הדיחו הראשון אכלו מלך אשור וזה האחרון עצמו נבוכדראצר מלך בבל לכן כה אמר ה' וגו' הנני פוקד אל מלך בבל ואל ארצו כאשר פקדתי על מלך אשור (ירמיהו נ יז) והנה זו ראיה שנענש מלך אשור על הרעה שעשה לישראל והנה נבוכדראצר שמע כי הנביאים פה אחד קוראים אותו להחריב ירושלים והוא וכל עמו נצטוו על כך מפי הנביא כמו שכתוב (ירמיהו כה ט) הנני שולח לך ולקחתי את כל משפחות צפון נאם ה' ואל נבוכדראצר מלך בבל עבדי והביאותים על הארץ הזאת ועל יושביה והחרמתים וכתיב (שם לב כח) הנני נותן את העיר הזאת ביד הכשדים וביד נבוכדראצר מלך בבל והציתו את העיר באש ואף על בית המקדש עצמו אמר (שם כו ו) ונתתי את הבית הזה כשילה והם יודעים כי מצות השם היא כמו שאמר נבוזראדן לירמיהו (שם מ ב) ה' אלהיך דבר את הרעה הזאת אל המקום הזה ויבא ויעש ה' כאשר דבר כי חטאתם לה' ואף על פי כן נענשו הכשדים כולם בסוף והיה זה מפני שני טעמים האחד שגם הוא נתכון להשמיד כל הארץ להגדיל ממשלתו כמו שכתוב בו (ישעיהו יג יא) והשבתי גאון זדים וגאות עריצים אשפיל וכתיב (שם יד יג) ואתה אמרת בלבבך השמים אעלה וגו' וכתוב אעלה על במתי עב אדמה לעליון וכתיב באומתו (שם מז ח) האומרת בלבבה אני ואפסי עוד ואמר בו חבקוק (חבקוק ב ט) הוי בוצע בצע רע לביתו לשום במרום קנו וגו' והנה זה כענשו של סנחריב ולכך אמר הכתוב (ירמיהו נ יח) לכן כה אמר ה' הנני פוקד אל מלך בבל ואל ארצו כאשר פקדתי על מלך אשור אבל היה במלך בבל עונש אחר שהוסיף על הגזרה והרע לישראל יותר מאד כמו שאמר בו (ישעיהו מז ו) קצפתי על עמי חללתי נחלתי ואתנם בידך לא שמת להם רחמים על זקן הכבדת עולך מאד ועל כן בא עליהם עונש כפול ומכופל שנשמד זרעו לגמרי ולא יהיה לבבל שם ושאר נין ונכד (ישעיהו יד כב) ונשמדה עירו לעולמים שנאמר (שם יג יט) והיתה בבל צבי ממלכות תפארת גאון כשדים כמהפכת אלהים את סדום ואת עמורה לא תשב לנצח ולא תשכון עד דור ודור ורבצו שם ציים ושעירים ירקדו שם ואמר בו הכתוב (ירמיהו נא יא) כי נקמת ה' היא נקמת היכלו וכתיב (שם נא לה לו) חמסי ושארי על בבל תאמר יושבת ציון ודמי אל יושבי כשדים תאמר ירושלים לכן כה אמר ה' הנני רב את ריבך ונקמתי את נקמתך ופסוקים רבים כאלה
@77 **ואתה תבא אל אבותיך בשלום** . ולא תראה כל אלה לשון רש"י ואינו נכון כפי פירושו שאמר (בפסוק יג) "כי גר יהיה זרעך" משיהיה לך זרע ומשנולד יצחק נאמר בו ויגר אברהם בארץ פלשתים (להלן כא לד) ויגר יצחק בגרר אם כן גם הוא בכלל הגזירה אבל טעמו ואתה תבא אל אבותיך בשלום שלא יגיעך שום עונש דבר מאתי אף על פי שאני גוזר על בניך עונשים בעבדות וענוי
@78 **ודור רביעי ישובו הנה** . לאחר שיגלו למצרים יהיו שלשה דורות וכן היה יעקב גולה צא וחשוב דורותיו יהודה פרץ חצרון וכלב בן חצרון מבאי הארץ היה לשון רש"י ואיננו נכון כלל והנכון בעיני כי "דור רביעי" לאמורי המשלים עונו כי מיום הגזירה האריך לו כי הוא פוקד עון על שלשים ועל רבעים כי אם ישובו לא יחרימם אבל יהיו למס עובד או יפנו להם
@78 "עון האמורי" - הזכיר התקיף שבהם אשר כגבה ארזים גבהו ולא יוכלו לו עד שתתמלא סאתו ועונותיו ילכדונו ועוד כי הוא הנלכד להם אשר הורישו בתחלה
@79 **והנה תנור עשן ולפיד אש** . ראה כאלו תנור עשן כולו ובתוכו לפיד אש בוערה כענין עשן גדול ואש מתלקחת (יחזקאל א ד) והעשן הוא הענן והערפל הנזכר במתן תורה (דברים ד יא) ולפיד האש בתוכו הוא האש האמור שם (ד לו) ודבריו שמעת מתוך האש וכתוב (שמות כד יז) ומראה כבוד ה' כאש אוכלת וגו' והנה השכינה עברה בין הבתרים והוא הברית אשר היתה אתו מעולם וזה טעם כרת ה' את אברם ברית כי הקב"ה בעצמו העביר ברית בין הבתרים והמשכיל יבין
@80 **ביום ההוא כרת ה' את אברם ברית לאמר** . הנה הקב"ה הבטיח את אברהם במתנת הארץ פעמים רבים וכולם לצורך ענין בבואו בארץ מתחלה אמר לו לזרעך אתן את הארץ הזאת (לעיל יב ז) ולא באר מתנתו כי אין במשמע רק במה שהלך בארץ עד מקום שכם עד אילון מורה ואחרי כן כשרבו זכיותיו בארץ הוסיף לו שא נא עיניך וראה צפונה ונגבה וקדמה וימה (לעיל יג יד) כי יתן לו כל הארצות ההן בכללן ואין הטעם אשר אתה רואה בעיניך כי ראות האדם איננו למרחק רק שיתן לו לכל מראה עיניו הרוחות או שהראהו כל ארץ ישראל כאשר היה במשה רבינו והוסיף לו בברכה השנית הזאת עוד ולזרעך עד עולם ושירבה זרעו כעפר הארץ ובפעם השלישית באר לו תחומי הארץ והזכיר לו כל העמים עשרה אומות והוסיף לכרות לו ברית עליהן שלא יגרום החטא וכאשר צוהו על המילה אמר לו לאחזת עולם (להלן יז ח) לאמר שאם יגלו ממנה עוד ישובו וינחלוה והוסיף והייתי להם לאלהים שהוא בכבודו ינהיג אותם ולא יהיו בממשלת כוכב ומזל או שר משרי מעלה כאשר יתבאר עוד בתורה (ויקרא יח כה) ואמר הכתוב בפעם הראשונה לזרעך אתן בלשון עתיד וכן בשנית כי עד הנה לא נתנה אליו כולה ולפיכך אמר לו אתננה אבל בשלישית בשעת הברית אמר לזרעך נתתי לאמר שיכרות לו ברית על המתנה שכבר נתן לו וכן בעת המילה כשאמר "לאחזת עולם" אמר לו "ונתתי לך" בעתיד ורש"י כתב לזרעך נתתי אמירת הגבוה כמו שהיא עשויה ואין צורך במקום הזה
@85 **וישמע אברם לקול שרי** . לא אמר הכתוב "ויעש כן" אבל אמר כי שמע לקול שרי ירמוז כי אף על פי שאברם מתאוה מאד לבנים לא עשה כן בלא רשות שרי וגם עתה לא נתכוון שיבנה הוא מהגר ויהיה זרעו ממנה אבל כל כוונתו לעשות רצון שרה שתבנה ממנה שיהיה לה נחת רוח בבני שפחתה או זכות שתזכה היא לבנים בעבור כן כדברי רבותינו (ב"ר מב ב עא ז) ואמר עוד ותקח שרי להודיע שלא מהר אברם לדבר עד שלקחה שרי ונתנה בחיקו והזכיר הכתוב שרי אשת אברם לאברם אישה לרמוז כי שרה לא נתיאשה מאברם ולא הרחיקה עצמה מאצלו כי היא אשתו והוא אישה אבל רצתה שתהיה גם הגר אשתו ולכך אמר לו לאשה שלא תהיה כפלגש רק כאשה נשואה לו וכל זה מוסר שרה והכבוד שהיא נוהגת בבעלה
@86 **מקץ עשר שנים** . מועד הקבוע לאשה ששהתה עם בעלה י' שנים ולא ילדה חייב לישא אחרת לשבת אברם בארץ כנען מגיד שאין ישיבת חוצה לארץ עולה לו מן המנין לפי שלא נאמר לו ואעשך לגוי גדול עד שבא לארץ ישראל לשון רש"י והטעם הזה איננו יפה שישיבת חוצה לארץ הלכה פסוקה היא שאינה עולה לשום אדם בעולם ומשנה ששנינו בה (יבמות סד) בכל אדם היא ואם היה מפני ההבטחה הזו לאברם היתה עולה לשאר האנשים וכבר טעו בה גם כן מן המפרשים טעות אחרת שאמרו שאין דין היושב בחוצה לארץ להוציא האשה ששהתה עמו עשר שנים ולא ילדה ולא שישא אחרת ואין הענין כן אבל הכוונה לומר שאם היה אדם עם אשתו בחוצה לארץ חמש או עשר שנים ובאו לארץ ישראל שנותנין להם זמן עשר שנים מעת ביאתם לארץ אולי בזכות הארץ יבנו וכן עשו אברהם ושרה מנו מעת בואם שם
@89 **ותענה שרי ותברח מפניה** . חטאה אמנו בענוי הזה וגם אברהם בהניחו לעשות כן ושמע ה' אל עניה ונתן לה בן שיהא פרא אדם לענות זרע אברהם ושרה בכל מיני הענוי
@92 **שובי אל גברתך והתעני תחת ידיה** . צוה אותה לשוב ולקבל עליה ממשלת גברתה רמז כי לא תצא לחפשי ממנה כי בני שרה ימשלו בזרעה לעולם
@94 **וקראת שמו ישמעאל** . הודיע המלאך להגר שיהיה שמו ישמעאל כדרך הנה בן נולד לבית דוד יאשיהו שמו (מלכים א יג ב) ואמר לה שהיא תקראנו כן ותזכור כי שמע אלהים אל עניה ואברהם מעצמו קרא שמו כן שישמע אל ויעננו או ששרתה עליו רוח הקודש כדברי רש"י וקרא אותו ישמעאל כי שמע אלהים אל עני אמו כדבר המלאך והנכון בעיני כי המלאך צוה להגר שתקראנה כן והיא יראה בעבור היותה פלגש לקרוא שם לבן אדוניה וגלתה לו הענין ואברם קיים דבר ה' אבל לא הוצרך הכתוב להאריך בזה
@95 **פרא אדם** . לשון רש"י אוהב מדברות לצוד חיות כמו שכתוב (להלן כא כ) וישב במדבר ויהי רובה קשת ידו בכל ליסטים ויד כל בו הכל שונאין אותו ומתגרין בו והנכון כי פרא אדם סמוך שיהיה איש פרא למוד מדבר יצא בפעלו משחר לטרף ויטרוף הכל והכל יטרפוהו והענין על זרעו שיגדל ויהיו להם מלחמות עם כל העמים ורבי אברהם אמר ידו בכל שינצח מתחלה כל הגוים ואחר כן יד כל בו שינוצח בסוף ועל פני כל אחיו שהם בני קטורה ישכון שיגדל זרעו מהם
@100 **אל שדי** . שני שמות כל אחד תאר לעצמו ופירוש "אל" תקיף מלשון אלי מואב (שמות טו טו) ופירוש "שדי" אמר רש"י שיש די באלהותי לכל בריה ובספר מורה הנבוכים (א סג) פירש הרב כלומר שאינו צריך במציאות מה שנמצא ולא בקיום מציאותו לזולתו אבל מציאותו תספיק בעצמה ורבי אברהם פירשו בשם הנגיד ז"ל מגזרת שודד כלומר מנצח ומשודד מערכות השמים וזהו הנכון כי היא מדת הגבורה מנהגת העולם שיאמרו בה החכמים (ב"ר לה ד) "מדת הדין של מטה" וטעם להזכיר עתה זה השם כי בו יעשו הנסים הנסתרים לצדיקים להציל ממות נפשם ולחיותם ברעב ולפדותם במלחמה מיד חרב ככל הנסים הנעשים לאברהם ולאבות וככל הבאים בתורה בפרשת אם בחקותי (ויקרא כו ג-מו) ובפרשת והיה כי תבא (דברים כח א-סח) בברכות ובקללות שכולם נסים הם כי אין מן הטבע שיבואו הגשמים בעתם בעבדנו האלהים ולא שיהיו השמים כברזל כאשר נזרע בשנה השביעית וכן כל היעודים שבתורה אבל כולם נסים ובכולם תתנצח מערכת המזלות אלא שאין בהם שנוי ממנהגו של עולם כנסים הנעשים על ידי משה רבינו בעשר המכות ובקריעת הים והמן והבאר וזולתם שהם מופתים משנים הטבע בפירסום והם שיעשו בשם המיוחד אשר הגיד לו ולכן אמר עתה לאברהם אבינו כי הוא התקיף המנצח שיגבר על מזלו ויוליד ויהיה ברית בינו ובין זרעו לעולם שיהיה חלק ה' עמו וברצונו ינהיגם לא יהיו תחת ממשלת כוכב ומזל ודע וראה כי אברהם אבינו לא הזכיר בדבריו שם יו"ד ה' רק בצירוף השם הכתוב באל"ף דל"ת או בצירוף אל עליון עמו ויזכיר בעניניו "אלהים" וכן יאמר ה' אלהי השמים (להלן כד ז) ואמר ה' יראה (להלן כב יד) על מקום המקדש העתיד ויעקב הזכיר תמיד "אל שדי" (להלן מג יד מח ג) ומשה רבינו לא יזכיר כן לעולם ואם תזכה תבין זה כולו ממה שאמרו במסכת יבמות (מט) כל הנביאים נסתכלו באיספקלריא שאינה מאירה ולפיכך אמר ישעיה ואראה את ה' (ישעיהו ו א) ומשה נסתכל באיספקלריא המאירה ולפיכך אמר כי לא יראני האדם וחי (שמות לג כ) ואראה את ה' כתוב באל"ף דל"ת ועוד אזכיר זה בפרשת וארא (שמות ו ב) אם יראה אלהים בעניי
@100 "התהלך לפני" - ללכת בדרך אשר אורה אותך כטעם אחרי ה' אלהיכם תלכו ואותו תיראו (דברים יג ה) כי המצוה לאחוז דרכו קודם שיורנו יאמר "התהלך לפני" והבא אחרי הצואה יאמר "אחרי ה' תלכו" והענין בשניהם ללכת אחרי השם לירא ממנו לבדו ולעשות מה שיצוה
@100 "והיה תמים" - מצוה אחרת עוד בענין הזה כטעם תמים תהיה עם ה' אלהיך (דברים יח יג) אחרי אזהרת השם לא ימצא בך קוסם קסמים מעונן ומנחש ומכשף וגו' (שם יח י) והענין בשניהם שיאמין בלבו כי הקב"ה לבדו הוא בעל היכולת בתחילה ובסוף הוא היכול לעשות ולבטל ולא ישמעו אל מעוננים ואל קוסמים או למנחש ומכשף ולא יאמין שיבאו דבריהם על כל פנים אבל יגזור בלבו שהכל ביד עליון העליונים שהוא "אל" והוא "אל שדי" עושה טובה שלא היה במזל ומביא רעה בהיות המזל טוב ויפה כפי שיתהלך האדם לפניו מפר אותות בדים וקוסמים יהולל (ישעיהו מד כה) וזהו שאמרו (שבת קנו) צא מאצטגנינות שלך וכו' ורש"י פירש והיה תמים היה שלם בכל הנסיונות ורבי אברהם אמר שלא ישאל על המילה למה והוא כטעם יהי לבי תמים בחקיך למען לא אבוש (תהלים קיט פ) והנכון מה שפרשתי
@102 **וטעם ויפול אברם על פניו** . לכוין דעתו לנבואה וכאשר השלים לו נבואת המצוה במילה קם אברהם ועמד ובא אליו הדיבור שנית מן השמים ואמר לו שרי אשתך וגו' וחזר ונפל על פניו לכוין דעתו והתפלל על ישמעאל כדרך ויפלו על פניהם ויאמרו אל אלהי הרוחות וגו' (במדבר טז כב) וכן ואכלה אותם כרגע ויפלו על פניהם (שם יז י)
@103 **הנה בריתי אתך והיית לאב המון גוים** . הוא ברית המילה כאשר יפרש זאת אות הברית ואחרי הברית תהיה לאב המון גוים וברוך השם אשר לו לבדו נתכנו עלילות שהקדים וצוה את אברהם לבא בבריתו להמול קודם שתהר שרה להיות זרעו קדוש (ראב"ע פסוק ה)
@105 **ונתתיך לגוים** . לשון רש"י ישראל ואדום שהרי ישמעאל כבר היה לו ולא היה מבשר עליו ואיננו נכון בעיני שיבשרנו בעת ברית המילה על עשו והוא אינו מקיים המילה וגם לא נצטוה עליה כמו שדרשו בסנהדרין (נט) כי ביצחק ולא כל יצחק אבל ישראל לבדם יקראו גוים ועמים וכן אף חובב עמים (דברים לג ג) עמים הר יקראו (שם יט) אחריך בנימין בעממיך (שופטים ה יד) גם אחרי הולדת השבטים כולם אמר גוי וקהל גוים יהיה ממך (להלן לה יא) ונתתיך לקהל עמים (להלן מח ד)
@108 **ואתה את בריתי תשמור** . כתב רש"י ו' מוסיף על ענין ראשון אני הנה בריתי אתך ואתה הוי זהיר לשמרו ומה שמירתו זאת בריתי אשר תשמרו אתם של עכשיו ובין זרעך אחריך העתידים להולד וצדק הרב בפשוטו ואמרו (הרד"ק) בטעם המילה ששם זכרון באבר התאוה רב המהומה והחטא לבל ישתמשו בו רק במצוה ובמותר ועל דרך האמת טעם "הנה בריתי אתך" כטעם "הנה אנכי עמך" (להלן כח טו) "ויאמר כי אהיה עמך" (שמות ג יב) "יהי ה' אלהינו עמנו" (מלכים א ח נז) יאמר כי הברית יהיה עמו ולכן יפרה וירבה ואחר כך צוה שישמור אברהם הברית הזאת ותהיה המילה לאות ברית והנה האות הזה אות כשבת ולכן ידחה אותו והבן זה (עי' זהר לך לך פט)
@113 **וערל זכר** . כאן לימדך שהמילה היא באותו מקום שהוא ניכר בין זכר לנקבה לשון רש"י וכן הזכירו רבותינו (ב"ר מו ד) גם טעמים אחרים ורבי אברהם אמר (ויקרא יב ג) ערלתו ידועה כי הוא בערוה ואין כן ערלת לב (ירמיהו ט כה) ושפה (שמות ו יב) ואזן (ירמיהו ו י) כי כולם סמוכים ולפי דעתי הדבר מפורש בכתוב כי לא אמר "ונמלתם את ערלתכם" שיהיה הדבר בספק וכן לא אמר "ערלת בשרכם" כמו שיאמר ערלת לבבכם (דברים י טז) וערלת שפתכם (עיי' שמות ו יב) אבל אמר "בשר ערלתכם" שתכרתו הבשר שהוא ערלה בכם כלומר הבשר האוטם בכם ואין בגוף בשר אוטם וכוסה אבר שיכרת הבשר ההוא וישאר בלא ערלה זולתי בשר החופה את העטרה שהזכירו חכמים (שבת קלז) ו"ערל בשר" (יחזקאל מד ט) כנוי כמו גדלי בשר (שם טז כו) זב מבשרו (ויקרא טו ב)
@116 **ויצחק** . תרגם אונקלוס "וחדי" וכן הדבר כי הצחוק פעם יאמר ללעג ופעם לשמחה כמו משחקת בתבל ארצו (משלי ח לא) משחקים לפני ה' ( ו ה) ולפי דעתי שהכונה בלשון הזה כי כל רואה ענין נפלא באדם לטוב לו ישמח עד ימלא שחוק פיו והוא מה שאמרה שרה (להלן כא ו) צחוק עשה לי אלהים כל השומע יצחק לי כענין אז ימלא שחוק פינו ולשוננו רנה (תהלים קכו ב) וכן עשה אברהם כאשר נאמר לו זה שמח ומלא שחוק פיו ויאמר בלבו ראוי זה לשחוק כי הוא ענין נפלא מאד הלבן מאה שנה יולד ואם שרה בת תשעים תלד ולא יהיה זה לשחוק ולשמחה ויקצר הכתוב בתמיהה כי היא נקשרת במה שאמר ויצחק וכן הגם הלום ראיתי (לעיל טז יג) נקשר בראש הפסוק כי אמרה הגם הלום ראיתי השם שנגלה לי כי ראה בעניי ולא אקראנו אל ראי וכן הנגלה נגליתי אל בית אביך (שמואל א ב כז) קשור עם "למה תבעטו בזבחי ובמנחתי" יאמר האם בחרתי בכם שתבעטו בזבחי ומנחתי ולמה תעשו כן או שתהיה הלבן מאה שנה בשאלה לדבר פלא לא כדבר נמנע כמו התשפוט את עיר הדמים (יחזקאל כב ב) ענינו התרצה לשפוט אותה ולהודיעה את כל תועבותיה וכן התעיף עיניך בו ואיננו (משלי כג ה) וכן המן העץ אשר צויתיך לבלתי אכל ממנו אכלת (לעיל ג יא) כלומר האם עלה בדעתך על הלב לאכול מן העץ וכן זה האם יעלה על הלב שלבן מאה שנה יוליד שרה בת תשעים שנה תלד ואחר כן אמר לו שיהיה הנס הזה עם חיי ישמעאל
@116 "הלבן מאה שנה יולד" - אין הפלא בבן מאה שנה שיוליד כי האנשים יולידו כל ימי היות בהם הליחה בני תשעים ובני מאה גם בדורות האלה אף כי בימי אברהם שלא עברו מימיו פי השנים והנה אחרי זה ארבעים שנה הוליד בנים רבים מקטורה אבל אמר הלבן מאה שנה שלא הוליד בבחרותו מן האשה הזאת יוליד ממנה עתה אחרי מאה ואחרי תשעים שפסק ממנה ארח נשים כי ידע כן ולכך לא אמר כן מתחלה כשנאמר לו (לעיל יז ו) "ונתתיך לגוים" עד אמרו אליו כי משרה יוליד וצוה אותו וקראת את שמו יצחק בעבור הצחוק שעשה אברהם וזה לאות כי היה לאמונה ולשמחה ואחרי שקרא אותו אברהם כן כאשר צוה ה' אותו אמרה שרה הכי קרא שמו יצחק כי צחוק עשה לי אלהים
@117 **לו ישמעאל יחיה לפניך** . פירוש המלה הזאת בכל מקום כטעם "אם" והורכבה במלת "לולי" (להלן לא מב) וטעמה "אם לא" ונכתבה לפעמים באל"ף (להלן מג י) וכן ירכיבוה עוד ויאמרו "אלו" ואלו לעבדים ולשפחות (אסתר ז ד) ואלו חיה אלף שנים פעמים (קהלת ו ו) וענין המלה "אם לו" וטעמה כמו "אם אם" ובא הכפל לחזוק כמו הרק אך במשה (במדבר יב ב) המבלי אין קברים (שמות יד יא) ודומיהם ואמר אברהם אם ישמעאל יחיה לפניך ארצה בברכה הזאת אשר ברכתני בזרע שרה כי הבטיחו מתחלה אשר יצא ממעיך הוא יירשך (לעיל טו ד) והנה היורש אותו יחיד והיה חושב שהוא ישמעאל ועתה כאשר נאמר לו כי משרה יוליד והבין כי הוא היורש פחד פן ימות ישמעאל ולכן אמר זה
@117 "יחיה לפניך" - פירש רש"י יחיה ביראתך כמו התהלך לפני (לעיל יז א) פלח קדמי ואיננו נכון בעבור שאמר ולישמעאל שמעתיך אבל פירושו יחיה ויתקיים זרעו כל ימי עולם
@118 **אבל שרה אשתך** . כמו אבל בן אין לה (מלכים ב ד יד) כטעם רק אמר רק הבן אשר אני מבשרך עליו שרה אשתך תלד אותו ובו אני מקים בריתי לעולם ובזרעו אחריו וישמעאל אברך להרבות זרעו אך לא מבריתי
@121 **ויעל אלהים מעל אברהם** . לשון כבוד כלפי המקום ולמדנו שהצדיקים מרכבתו של הקב"ה לשון רש"י אבל לשונם בבראשית רבה (מז ו) האבות הן הן המרכבה ירמוז למה שכתוב (מיכה ז כ) תתן אמת ליעקב חסד לאברהם ופחד יצחק היה לי (להלן לא מב) והמשכיל יבין
@125 **בעצם היום הזה** . כתב רש"י בעצם היום הזה שמלאו לאברהם צ"ט שנה ולישמעאל י"ג נמולו ומה טעם להזכיר זה ועוד שכבר הסכימו (ר"ה י) לדברי רבי אליעזר שבתשרי נברא העולם ובתשרי נולדו אבות ובפסח נולד יצחק והכתוב אמר למועד הזה בשנה האחרת והוא כתב בסדר וירא (יח י) כי הבשורה היתה בפסח ולפסח הבא נולד יצחק אבל בעצם היום הזה שנצטוה במצוה הזאת נימול הוא וילידי ביתו שמנה עשר ושלש מאות וכל מקנת כספו סיפר הכתוב מעלתו ביראת ה' ומעלת כל בני ביתו שכולם זריזים מקדימין למצות ואין טעם נימול אברהם שנימול הוא בתחלה אבל ישמעאל בנו נימול מתחלה וכל בני ביתו כי כן כתוב (לעיל פסוק כג) ויקח אברהם את ישמעאל בנו ואת כל ילידי ביתו ואחרי כן ואברהם בן תשעים ותשע שנה בהמולו והטעם כי אברהם נזדרז במצות המילה שלהם תחילה ומל אותם הוא בעצמו או שזימן להם מוהלים הרבה והוא עומד עליהם ואחר כך מל את עצמו שאילו הקדים מילתו היה חולה או מסוכן בה מפני זקנתו ולא היה יכול להשתדל במילתם חסלת פרשת לך לך
